import { useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const REFRESH_INTERVAL_MS = 10_000;

async function fetchMetrics(): Promise<Metric[]> {
  const res = await fetch("/api/metrics");
  if (!res.ok) {
    throw new Error(`Failed to load metrics: ${res.status}`);
  }
  return res.json() as Promise<Metric[]>;
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [secondsAgo, setSecondsAgo] = useState(0);

  const previousMetricsRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    let cancelled = false;
    let intervalId: ReturnType<typeof setInterval> | undefined;

    const refresh = async () => {
      if (document.hidden) return;
      try {
        const next = await fetchMetrics();
        if (cancelled) return;

        const previous = previousMetricsRef.current;
        const changed = new Set<string>();
        for (const metric of next) {
          const prevValue = previous.get(metric.name);
          if (prevValue !== undefined && prevValue !== metric.value) {
            changed.add(metric.name);
          }
        }

        previousMetricsRef.current = new Map(
          next.map((metric) => [metric.name, metric.value]),
        );
        setMetrics(next);
        setChangedNames(changed);
        setLastUpdated(new Date());
        setError(null);
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Failed to load metrics");
        }
      }
    };

    const startInterval = () => {
      if (intervalId !== undefined) return;
      intervalId = setInterval(refresh, REFRESH_INTERVAL_MS);
    };

    const stopInterval = () => {
      if (intervalId === undefined) return;
      clearInterval(intervalId);
      intervalId = undefined;
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopInterval();
      } else {
        refresh();
        startInterval();
      }
    };

    refresh();
    startInterval();
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      cancelled = true;
      stopInterval();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    if (!lastUpdated) return;
    const tick = () => {
      setSecondsAgo(Math.max(0, Math.round((Date.now() - lastUpdated.getTime()) / 1000)));
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [lastUpdated]);

  return (
    <div className="metrics-panel">
      <div className="metrics-panel__header">
        <h2>Metrics</h2>
        {lastUpdated && (
          <span className="metrics-panel__timestamp">
            Last updated {secondsAgo} second{secondsAgo === 1 ? "" : "s"} ago
          </span>
        )}
      </div>

      {error && <p className="metrics-panel__error">{error}</p>}

      <ul className="metrics-panel__list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={
              changedNames.has(metric.name)
                ? "metrics-panel__item metrics-panel__item--changed"
                : "metrics-panel__item"
            }
          >
            <span className="metrics-panel__name">{metric.name}</span>
            <span className="metrics-panel__value">
              {metric.value} {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const REFRESH_INTERVAL_MS = 10_000;

function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    typeof candidate.unit === "string"
  );
}

function parseMetrics(data: unknown): Metric[] {
  if (!Array.isArray(data) || !data.every(isMetric)) {
    throw new Error("Received malformed metrics data");
  }
  return data;
}

function useElapsedSeconds(since: number | null): number {
  const [now, setNow] = useState(() => Date.now());

  useEffect(() => {
    if (since === null) return;
    const id = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(id);
  }, [since]);

  if (since === null) return 0;
  return Math.max(0, Math.round((now - since) / 1000));
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);
  const previousValuesRef = useRef<Map<string, number>>(new Map());
  const inFlightRef = useRef<AbortController | null>(null);

  const secondsAgo = useElapsedSeconds(lastUpdated);

  const fetchMetrics = useCallback(async () => {
    if (inFlightRef.current) {
      return;
    }
    const controller = new AbortController();
    inFlightRef.current = controller;

    try {
      const response = await fetch("/api/metrics", { signal: controller.signal });
      if (!response.ok) {
        throw new Error(`Request failed with status ${response.status}`);
      }
      const fetchedMetrics = parseMetrics(await response.json());

      if (controller.signal.aborted) return;

      const previousValues = previousValuesRef.current;
      const nextChanged = new Set<string>();
      const nextValues = new Map<string, number>();
      for (const metric of fetchedMetrics) {
        nextValues.set(metric.name, metric.value);
        const previousValue = previousValues.get(metric.name);
        if (previousValue !== undefined && previousValue !== metric.value) {
          nextChanged.add(metric.name);
        }
      }

      previousValuesRef.current = nextValues;
      setMetrics(fetchedMetrics);
      setChangedNames(nextChanged);
      setLastUpdated(Date.now());
      setError(null);
    } catch (err) {
      if (controller.signal.aborted) return;
      setError(err instanceof Error ? err.message : "Failed to load metrics");
    } finally {
      if (inFlightRef.current === controller) {
        inFlightRef.current = null;
      }
    }
  }, []);

  useEffect(() => {
    fetchMetrics();

    let intervalId: number | undefined;

    const startPolling = () => {
      if (intervalId !== undefined) return;
      intervalId = window.setInterval(fetchMetrics, REFRESH_INTERVAL_MS);
    };

    const stopPolling = () => {
      if (intervalId === undefined) return;
      window.clearInterval(intervalId);
      intervalId = undefined;
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopPolling();
      } else {
        fetchMetrics();
        startPolling();
      }
    };

    if (!document.hidden) {
      startPolling();
    }

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      stopPolling();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      inFlightRef.current?.abort();
    };
  }, [fetchMetrics]);

  return (
    <div className="metrics-panel">
      <div className="metrics-panel__header">
        <h2>Metrics</h2>
        <span className="metrics-panel__last-updated">
          {lastUpdated === null
            ? "Loading…"
            : `Last updated ${secondsAgo} second${secondsAgo === 1 ? "" : "s"} ago`}
        </span>
      </div>

      {error && <div className="metrics-panel__error">{error}</div>}

      <ul className="metrics-panel__list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={
              changedNames.has(metric.name)
                ? "metrics-panel__item metrics-panel__item--changed"
                : "metrics-panel__item"
            }
          >
            <span className="metrics-panel__name">{metric.name}</span>
            <span className="metrics-panel__value">
              {metric.value} {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const REFRESH_INTERVAL_MS = 10_000;

function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    typeof candidate.unit === "string"
  );
}

function isMetricArray(value: unknown): value is Metric[] {
  return Array.isArray(value) && value.every(isMetric);
}

function formatSecondsAgo(seconds: number): string {
  if (seconds <= 1) return "just now";
  return `${seconds} seconds ago`;
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [, setTick] = useState(0);

  const previousValuesRef = useRef<Map<string, number>>(new Map());
  const inFlightRef = useRef<AbortController | null>(null);

  const fetchMetrics = useCallback(async () => {
    inFlightRef.current?.abort();
    const controller = new AbortController();
    inFlightRef.current = controller;

    try {
      const response = await fetch("/api/metrics", { signal: controller.signal });
      if (!response.ok) {
        throw new Error(`Request failed with status ${response.status}`);
      }
      const data: unknown = await response.json();
      if (!isMetricArray(data)) {
        throw new Error("Unexpected response shape from /api/metrics");
      }

      if (controller.signal.aborted) return;

      const previousValues = previousValuesRef.current;
      const nextChanged = new Set<string>();
      const nextValues = new Map<string, number>();

      for (const metric of data) {
        nextValues.set(metric.name, metric.value);
        const previousValue = previousValues.get(metric.name);
        if (previousValue !== undefined && previousValue !== metric.value) {
          nextChanged.add(metric.name);
        }
      }

      previousValuesRef.current = nextValues;
      setMetrics(data);
      setChangedNames(nextChanged);
      setLastUpdated(new Date());
      setError(null);
    } catch (err) {
      if (err instanceof DOMException && err.name === "AbortError") return;
      setError(err instanceof Error ? err.message : "Failed to load metrics");
    } finally {
      if (inFlightRef.current === controller) {
        inFlightRef.current = null;
      }
    }
  }, []);

  useEffect(() => {
    fetchMetrics();

    let intervalId: ReturnType<typeof setInterval> | null = null;

    const startPolling = () => {
      if (intervalId === null) {
        intervalId = setInterval(fetchMetrics, REFRESH_INTERVAL_MS);
      }
    };

    const stopPolling = () => {
      if (intervalId !== null) {
        clearInterval(intervalId);
        intervalId = null;
      }
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopPolling();
      } else {
        fetchMetrics();
        startPolling();
      }
    };

    if (!document.hidden) {
      startPolling();
    }

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      stopPolling();
      inFlightRef.current?.abort();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [fetchMetrics]);

  // Re-render once a second so the "seconds ago" label stays live; the value
  // itself is computed below from lastUpdated + the current time, not stored.
  useEffect(() => {
    const tickId = setInterval(() => setTick((t) => t + 1), 1000);
    return () => clearInterval(tickId);
  }, []);

  const secondsAgo = lastUpdated
    ? Math.floor((Date.now() - lastUpdated.getTime()) / 1000)
    : 0;

  return (
    <div className="metrics-panel">
      <div className="metrics-panel-header">
        <h2>Metrics</h2>
        {lastUpdated && (
          <span className="metrics-panel-updated">
            Last updated {formatSecondsAgo(secondsAgo)}
          </span>
        )}
      </div>

      {error && <div className="metrics-panel-error">{error}</div>}

      <ul className="metrics-panel-list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={
              changedNames.has(metric.name)
                ? "metrics-panel-item metrics-panel-item-changed"
                : "metrics-panel-item"
            }
          >
            <span className="metrics-panel-item-name">{metric.name}</span>
            <span className="metrics-panel-item-value">
              {metric.value}
              {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, FormEvent } from "react";

interface FormValues {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<keyof FormValues, string>>;

const initialValues: FormValues = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(values: FormValues): FieldErrors {
  const errors: FieldErrors = {};

  if (!values.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!values.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(values.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!values.password) {
    errors.password = "Password is required.";
  } else if (values.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!values.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (values.confirmPassword !== values.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!values.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

interface SignupSuccessResponse {
  id: string;
}

interface SignupErrorResponse {
  errors: Partial<Record<keyof FormValues, string>>;
}

function isSignupErrorResponse(data: unknown): data is SignupErrorResponse {
  return (
    typeof data === "object" &&
    data !== null &&
    "errors" in data &&
    typeof (data as { errors: unknown }).errors === "object"
  );
}

export default function SignupForm() {
  const [values, setValues] = useState<FormValues>(initialValues);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [accountId, setAccountId] = useState<string | null>(null);

  function handleChange(
    field: keyof FormValues,
    value: string | boolean
  ) {
    setValues((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitError(null);
    setAccountId(null);

    const validationErrors = validate(values);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    setIsSubmitting(true);
    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: values.name,
          email: values.email,
          password: values.password,
        }),
      });

      const data: unknown = await response.json();

      if (!response.ok) {
        if (isSignupErrorResponse(data)) {
          setErrors(data.errors);
        } else {
          setSubmitError("Signup failed. Please try again.");
        }
        return;
      }

      const { id } = data as SignupSuccessResponse;
      setAccountId(id);
      setValues(initialValues);
      setErrors({});
    } catch {
      setSubmitError("Something went wrong. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      {accountId && (
        <div role="status">
          Account created successfully! Your account id is {accountId}.
        </div>
      )}
      {submitError && <div role="alert">{submitError}</div>}

      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          type="text"
          value={values.name}
          onChange={(e) => handleChange("name", e.target.value)}
        />
        {errors.name && <span role="alert">{errors.name}</span>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={values.email}
          onChange={(e) => handleChange("email", e.target.value)}
        />
        {errors.email && <span role="alert">{errors.email}</span>}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={values.password}
          onChange={(e) => handleChange("password", e.target.value)}
        />
        {errors.password && <span role="alert">{errors.password}</span>}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm password</label>
        <input
          id="confirmPassword"
          type="password"
          value={values.confirmPassword}
          onChange={(e) => handleChange("confirmPassword", e.target.value)}
        />
        {errors.confirmPassword && (
          <span role="alert">{errors.confirmPassword}</span>
        )}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            type="checkbox"
            checked={values.acceptTerms}
            onChange={(e) => handleChange("acceptTerms", e.target.checked)}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && <span role="alert">{errors.acceptTerms}</span>}
      </div>

      <button type="submit" disabled={isSubmitting}>
        {isSubmitting ? "Signing up..." : "Sign up"}
      </button>
    </form>
  );
}

import { useState, FormEvent } from "react";

interface FormState {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<keyof FormState, string>>;

const INITIAL_STATE: FormState = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(form: FormState): FieldErrors {
  const errors: FieldErrors = {};

  if (!form.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!form.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(form.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!form.password) {
    errors.password = "Password is required.";
  } else if (form.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!form.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (form.confirmPassword !== form.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!form.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

interface SignupResponse {
  id: string;
}

interface SignupErrorResponse {
  errors: Partial<Record<string, string>>;
}

function isSignupResponse(value: unknown): value is SignupResponse {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as { id?: unknown }).id === "string"
  );
}

function isSignupErrorResponse(value: unknown): value is SignupErrorResponse {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as { errors?: unknown }).errors === "object" &&
    (value as { errors?: unknown }).errors !== null
  );
}

export default function SignupForm() {
  const [form, setForm] = useState<FormState>(INITIAL_STATE);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [successId, setSuccessId] = useState<string | null>(null);

  function updateField<K extends keyof FormState>(field: K, value: FormState[K]) {
    setForm((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitError(null);
    setSuccessId(null);

    const clientErrors = validate(form);
    if (Object.keys(clientErrors).length > 0) {
      setErrors(clientErrors);
      return;
    }

    setSubmitting(true);
    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: form.name,
          email: form.email,
          password: form.password,
          confirmPassword: form.confirmPassword,
        }),
      });

      if (!response.ok) {
        const errorBody: unknown = await response.json().catch(() => null);
        if (isSignupErrorResponse(errorBody)) {
          setErrors(errorBody.errors as FieldErrors);
        } else {
          setSubmitError("Something went wrong. Please try again.");
        }
        return;
      }

      const successBody: unknown = await response.json();
      if (!isSignupResponse(successBody)) {
        setSubmitError("Unexpected response from server.");
        return;
      }
      setSuccessId(successBody.id);
      setForm(INITIAL_STATE);
      setErrors({});
    } catch {
      setSubmitError("Network error. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <h1>Create an account</h1>

      {successId && (
        <p role="status">Account created successfully! Your account id is {successId}.</p>
      )}
      {submitError && <p role="alert">{submitError}</p>}

      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          type="text"
          value={form.name}
          onChange={(e) => updateField("name", e.target.value)}
          aria-invalid={Boolean(errors.name)}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && <p id="name-error">{errors.name}</p>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={form.email}
          onChange={(e) => updateField("email", e.target.value)}
          aria-invalid={Boolean(errors.email)}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && <p id="email-error">{errors.email}</p>}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={form.password}
          onChange={(e) => updateField("password", e.target.value)}
          aria-invalid={Boolean(errors.password)}
          aria-describedby={errors.password ? "password-error" : undefined}
        />
        {errors.password && <p id="password-error">{errors.password}</p>}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm password</label>
        <input
          id="confirmPassword"
          type="password"
          value={form.confirmPassword}
          onChange={(e) => updateField("confirmPassword", e.target.value)}
          aria-invalid={Boolean(errors.confirmPassword)}
          aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
        />
        {errors.confirmPassword && <p id="confirmPassword-error">{errors.confirmPassword}</p>}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            type="checkbox"
            checked={form.acceptTerms}
            onChange={(e) => updateField("acceptTerms", e.target.checked)}
            aria-invalid={Boolean(errors.acceptTerms)}
            aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && <p id="acceptTerms-error">{errors.acceptTerms}</p>}
      </div>

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up..." : "Sign up"}
      </button>
    </form>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

interface ChatRoomProps {
  roomId: string;
}

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.author === "string" &&
    typeof candidate.text === "string" &&
    typeof candidate.sentAt === "string"
  );
}

const RECONNECT_DELAY_MS = 2000;

export default function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [isReconnecting, setIsReconnecting] = useState(false);

  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const messagesEndRef = useRef<HTMLDivElement | null>(null);
  const isUnmountedRef = useRef(false);

  useEffect(() => {
    setMessages([]);
    isUnmountedRef.current = false;

    let hasConnectedOnce = false;

    const connect = () => {
      const socket = new WebSocket(`wss://chat.example.com/rooms/${roomId}`);
      socketRef.current = socket;

      socket.addEventListener("open", () => {
        if (hasConnectedOnce) {
          setIsReconnecting(false);
        }
        hasConnectedOnce = true;
      });

      socket.addEventListener("message", (event) => {
        try {
          const parsed: unknown = JSON.parse(event.data as string);
          if (isChatMessage(parsed)) {
            setMessages((prev) => [...prev, parsed]);
          }
        } catch {
          // ignore malformed message payloads
        }
      });

      const scheduleReconnect = () => {
        if (isUnmountedRef.current) return;
        setIsReconnecting(true);
        reconnectTimerRef.current = setTimeout(connect, RECONNECT_DELAY_MS);
      };

      socket.addEventListener("close", scheduleReconnect);
      socket.addEventListener("error", () => {
        socket.close();
      });
    };

    connect();

    return () => {
      isUnmountedRef.current = true;
      if (reconnectTimerRef.current !== null) {
        clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      const socket = socketRef.current;
      if (socket) {
        socket.onclose = null;
        socket.close();
        socketRef.current = null;
      }
      setIsReconnecting(false);
    };
  }, [roomId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = useCallback(() => {
    const text = draft.trim();
    const socket = socketRef.current;
    if (!text || !socket || socket.readyState !== WebSocket.OPEN) return;

    socket.send(JSON.stringify({ text }));
    setDraft("");
  }, [draft]);

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    sendMessage();
  };

  return (
    <div className="chat-room">
      {isReconnecting && (
        <div className="chat-room__banner" role="status">
          Reconnecting…
        </div>
      )}
      <div className="chat-room__messages">
        {messages.map((message) => (
          <div key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__time">
              {new Date(message.sentAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>
      <form className="chat-room__composer" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type FormEvent,
} from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string | number;
}

interface ChatRoomProps {
  roomId: string;
}

const RECONNECT_DELAY_MS = 2000;

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    typeof v.author === "string" &&
    typeof v.text === "string" &&
    (typeof v.sentAt === "string" || typeof v.sentAt === "number")
  );
}

export default function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [reconnecting, setReconnecting] = useState(false);
  const [draft, setDraft] = useState("");

  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const messagesEndRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    let cancelled = false;
    setMessages([]);
    setReconnecting(false);

    const connect = () => {
      if (cancelled) return;

      const socket = new WebSocket(
        `wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`,
      );
      socketRef.current = socket;

      socket.onopen = () => {
        if (cancelled) return;
        setReconnecting(false);
      };

      socket.onmessage = (event: MessageEvent<string>) => {
        if (cancelled) return;
        try {
          const parsed: unknown = JSON.parse(event.data);
          if (isChatMessage(parsed)) {
            setMessages((prev) => [...prev, parsed]);
          } else {
            console.warn("Received malformed chat message payload", parsed);
          }
        } catch (error) {
          console.warn("Failed to parse chat message payload", error);
        }
      };

      socket.onclose = () => {
        if (cancelled) return;
        setReconnecting(true);
        reconnectTimerRef.current = setTimeout(connect, RECONNECT_DELAY_MS);
      };

      socket.onerror = () => {
        socket.close();
      };
    };

    connect();

    return () => {
      cancelled = true;
      if (reconnectTimerRef.current !== null) {
        clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      const socket = socketRef.current;
      if (socket) {
        socket.onopen = null;
        socket.onmessage = null;
        socket.onclose = null;
        socket.onerror = null;
        socket.close();
        socketRef.current = null;
      }
    };
  }, [roomId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = useCallback(() => {
    const text = draft.trim();
    if (!text) return;

    const socket = socketRef.current;
    if (!socket || socket.readyState !== WebSocket.OPEN) return;

    socket.send(JSON.stringify({ text }));
    setDraft("");
  }, [draft]);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    sendMessage();
  };

  return (
    <div className="chat-room">
      {reconnecting && (
        <div className="chat-room__banner" role="status">
          Reconnecting…
        </div>
      )}

      <div className="chat-room__messages">
        {messages.map((message) => (
          <div key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__time">
              {new Date(message.sentAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form className="chat-room__composer" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import type { FormEvent } from "react";

interface TodoItem {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function loadInitialItems(): TodoItem[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (item): item is TodoItem =>
        typeof item === "object" &&
        item !== null &&
        typeof item.id === "string" &&
        typeof item.text === "string" &&
        typeof item.done === "boolean"
    );
  } catch {
    return [];
  }
}

function createId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export default function TodoBoard() {
  const [items, setItems] = useState<TodoItem[]>(loadInitialItems);
  const [newText, setNewText] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  const remainingCount = useMemo(
    () => items.filter((item) => !item.done).length,
    [items]
  );

  const visibleItems = useMemo(() => {
    switch (filter) {
      case "active":
        return items.filter((item) => !item.done);
      case "done":
        return items.filter((item) => item.done);
      default:
        return items;
    }
  }, [items, filter]);

  function handleAdd(event: FormEvent) {
    event.preventDefault();
    const text = newText.trim();
    if (!text) return;
    setItems((prev) => [...prev, { id: createId(), text, done: false }]);
    setNewText("");
  }

  function toggleDone(id: string) {
    setItems((prev) =>
      prev.map((item) =>
        item.id === id ? { ...item, done: !item.done } : item
      )
    );
  }

  function deleteItem(id: string) {
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEditing(item: TodoItem) {
    setEditingId(item.id);
    setEditingText(item.text);
  }

  function cancelEditing() {
    setEditingId(null);
    setEditingText("");
  }

  function commitEditing(id: string) {
    const text = editingText.trim();
    if (!text) {
      deleteItem(id);
      return;
    }
    setItems((prev) =>
      prev.map((item) => (item.id === id ? { ...item, text } : item))
    );
    setEditingId(null);
    setEditingText("");
  }

  function moveItem(id: string, direction: -1 | 1) {
    setItems((prev) => {
      const index = prev.findIndex((item) => item.id === id);
      const targetIndex = index + direction;
      if (index === -1 || targetIndex < 0 || targetIndex >= prev.length) {
        return prev;
      }
      const next = [...prev];
      const [moved] = next.splice(index, 1);
      next.splice(targetIndex, 0, moved);
      return next;
    });
  }

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form onSubmit={handleAdd} className="todo-add-form">
        <input
          type="text"
          value={newText}
          onChange={(event) => setNewText(event.target.value)}
          placeholder="Add a new todo"
          aria-label="New todo text"
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-filters" role="group" aria-label="Filter todos">
        {(["all", "active", "done"] as Filter[]).map((option) => (
          <button
            key={option}
            type="button"
            onClick={() => setFilter(option)}
            aria-pressed={filter === option}
            disabled={filter === option}
          >
            {option[0].toUpperCase() + option.slice(1)}
          </button>
        ))}
      </div>

      <p className="todo-remaining-count">
        {remainingCount} item{remainingCount === 1 ? "" : "s"} remaining
      </p>

      <ul className="todo-list">
        {visibleItems.map((item) => {
          const index = items.indexOf(item);
          const isEditing = editingId === item.id;
          return (
            <li key={item.id} className="todo-item">
              <input
                type="checkbox"
                checked={item.done}
                onChange={() => toggleDone(item.id)}
                aria-label={`Mark "${item.text}" as ${
                  item.done ? "active" : "done"
                }`}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(event) => setEditingText(event.target.value)}
                  onBlur={() => commitEditing(item.id)}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      event.preventDefault();
                      commitEditing(item.id);
                    } else if (event.key === "Escape") {
                      event.preventDefault();
                      cancelEditing();
                    }
                  }}
                />
              ) : (
                <span
                  className={item.done ? "todo-text todo-text-done" : "todo-text"}
                  onDoubleClick={() => startEditing(item)}
                >
                  {item.text}
                </span>
              )}

              <button
                type="button"
                onClick={() => moveItem(item.id, -1)}
                disabled={index <= 0}
                aria-label={`Move "${item.text}" up`}
              >
                ↑
              </button>
              <button
                type="button"
                onClick={() => moveItem(item.id, 1)}
                disabled={index === -1 || index >= items.length - 1}
                aria-label={`Move "${item.text}" down`}
              >
                ↓
              </button>
              {isEditing ? (
                <button type="button" onClick={() => commitEditing(item.id)}>
                  Save
                </button>
              ) : (
                <button type="button" onClick={() => startEditing(item)}>
                  Edit
                </button>
              )}
              <button type="button" onClick={() => deleteItem(item.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board-items";

function loadTodos(): Todo[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (item): item is Todo =>
        typeof item === "object" &&
        item !== null &&
        typeof item.id === "string" &&
        typeof item.text === "string" &&
        typeof item.done === "boolean"
    );
  } catch {
    return [];
  }
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [hydrated, setHydrated] = useState(false);
  const [filter, setFilter] = useState<Filter>("all");
  const [newText, setNewText] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    setTodos(loadTodos());
    setHydrated(true);
  }, []);

  useEffect(() => {
    if (!hydrated) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }, [todos, hydrated]);

  const remainingCount = useMemo(
    () => todos.filter((todo) => !todo.done).length,
    [todos]
  );

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function addTodo() {
    const text = newText.trim();
    if (!text) return;
    const todo: Todo = {
      id: crypto.randomUUID(),
      text,
      done: false,
    };
    setTodos((prev) => [...prev, todo]);
    setNewText("");
  }

  function toggleDone(id: string) {
    setTodos((prev) =>
      prev.map((todo) => (todo.id === id ? { ...todo, done: !todo.done } : todo))
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEditing(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function commitEditing() {
    const text = editingText.trim();
    if (editingId === null) return;
    if (text) {
      setTodos((prev) =>
        prev.map((todo) => (todo.id === editingId ? { ...todo, text } : todo))
      );
    }
    setEditingId(null);
    setEditingText("");
  }

  function cancelEditing() {
    setEditingId(null);
    setEditingText("");
  }

  function moveUp(id: string) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      if (index <= 0) return prev;
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
  }

  function moveDown(id: string) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      if (index === -1 || index >= prev.length - 1) return prev;
      const next = [...prev];
      [next[index], next[index + 1]] = [next[index + 1], next[index]];
      return next;
    });
  }

  return (
    <div>
      <h1>Todo Board</h1>

      <form
        onSubmit={(event) => {
          event.preventDefault();
          addTodo();
        }}
      >
        <input
          type="text"
          value={newText}
          onChange={(event) => setNewText(event.target.value)}
          placeholder="Add a todo"
        />
        <button type="submit">Add</button>
      </form>

      <div>
        <button
          type="button"
          onClick={() => setFilter("all")}
          disabled={filter === "all"}
        >
          All
        </button>
        <button
          type="button"
          onClick={() => setFilter("active")}
          disabled={filter === "active"}
        >
          Active
        </button>
        <button
          type="button"
          onClick={() => setFilter("done")}
          disabled={filter === "done"}
        >
          Done
        </button>
      </div>

      <p>{remainingCount} item{remainingCount === 1 ? "" : "s"} remaining</p>

      <ul>
        {visibleTodos.map((todo) => {
          const index = todos.findIndex((item) => item.id === todo.id);
          const isEditing = editingId === todo.id;
          return (
            <li key={todo.id}>
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
              />
              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(event) => setEditingText(event.target.value)}
                  onBlur={commitEditing}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      event.preventDefault();
                      commitEditing();
                    } else if (event.key === "Escape") {
                      event.preventDefault();
                      cancelEditing();
                    }
                  }}
                />
              ) : (
                <span
                  onDoubleClick={() => startEditing(todo)}
                  style={{ textDecoration: todo.done ? "line-through" : "none" }}
                >
                  {todo.text}
                </span>
              )}
              <button
                type="button"
                onClick={() => moveUp(todo.id)}
                disabled={index <= 0}
              >
                ↑
              </button>
              <button
                type="button"
                onClick={() => moveDown(todo.id)}
                disabled={index === todos.length - 1}
              >
                ↓
              </button>
              {!isEditing && (
                <button type="button" onClick={() => startEditing(todo)}>
                  Edit
                </button>
              )}
              <button type="button" onClick={() => deleteTodo(todo.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

interface ChatRoomProps {
  roomId: string;
}

const RECONNECT_DELAY_MS = 2000;

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    typeof v.author === "string" &&
    typeof v.text === "string" &&
    typeof v.sentAt === "string"
  );
}

export default function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [isReconnecting, setIsReconnecting] = useState(false);

  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const bottomRef = useRef<HTMLDivElement | null>(null);
  const closedByEffectRef = useRef(false);

  useEffect(() => {
    setMessages([]);
    setIsReconnecting(false);
    closedByEffectRef.current = false;

    let socket: WebSocket | null = null;

    const connect = () => {
      socket = new WebSocket(`wss://chat.example.com/rooms/${roomId}`);
      socketRef.current = socket;

      socket.addEventListener("open", () => {
        setIsReconnecting(false);
      });

      socket.addEventListener("message", (event) => {
        let parsed: unknown;
        try {
          parsed = JSON.parse(event.data);
        } catch (err) {
          console.error("Failed to parse chat message payload", err);
          return;
        }
        if (isChatMessage(parsed)) {
          setMessages((prev) => [...prev, parsed]);
        }
      });

      socket.addEventListener("close", () => {
        if (closedByEffectRef.current) return;
        setIsReconnecting(true);
        reconnectTimerRef.current = setTimeout(connect, RECONNECT_DELAY_MS);
      });

      socket.addEventListener("error", () => {
        socket?.close();
      });
    };

    connect();

    return () => {
      closedByEffectRef.current = true;
      if (reconnectTimerRef.current !== null) {
        clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      socketRef.current?.close();
      socketRef.current = null;
    };
  }, [roomId]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = () => {
    const text = draft.trim();
    if (!text) return;
    const socket = socketRef.current;
    if (!socket || socket.readyState !== WebSocket.OPEN) return;

    socket.send(JSON.stringify({ text }));
    setDraft("");
  };

  return (
    <div className="chat-room">
      {isReconnecting && <div className="chat-room__banner">Reconnecting…</div>}

      <div className="chat-room__messages">
        {messages.map((message) => (
          <div key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__time">
              {new Date(message.sentAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>

      <form
        className="chat-room__composer"
        onSubmit={(event) => {
          event.preventDefault();
          sendMessage();
        }}
      >
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  isLoading: boolean;
  errors: Record<string, string>;
}

export function useUserProfiles(userIds: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isLoading, setIsLoading] = useState(userIds.length > 0);

  useEffect(() => {
    if (userIds.length === 0) {
      setProfiles({});
      setErrors({});
      setIsLoading(false);
      return;
    }

    let cancelled = false;
    setIsLoading(true);
    setProfiles({});
    setErrors({});

    type ProfileResult =
      | { status: "success"; id: string; user: User }
      | { status: "error"; id: string; error: string };

    Promise.all(
      userIds.map(async (id): Promise<ProfileResult> => {
        try {
          const response = await fetch(`/api/users/${id}`);
          if (!response.ok) {
            throw new Error(`Request failed with status ${response.status}`);
          }
          const user = (await response.json()) as User;
          return { status: "success", id, user };
        } catch (err) {
          return {
            status: "error",
            id,
            error: err instanceof Error ? err.message : "Failed to load user",
          };
        }
      })
    ).then((results) => {
      if (cancelled) return;

      const nextProfiles: Record<string, User> = {};
      const nextErrors: Record<string, string> = {};
      for (const result of results) {
        if (result.status === "success") {
          nextProfiles[result.id] = result.user;
        } else {
          nextErrors[result.id] = result.error;
        }
      }
      setProfiles(nextProfiles);
      setErrors(nextErrors);
      setIsLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [userIds.join(",")]);

  return { profiles, isLoading, errors };
}

