import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.name === "string" &&
    typeof candidate.email === "string"
  );
}

function isUserArray(value: unknown): value is User[] {
  return Array.isArray(value) && value.every(isUser);
}

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  // Debounce requires a timer side effect; it can't be derived during render.
  useEffect(() => {
    const debounceTimeoutId = setTimeout(() => setDebouncedQuery(query), DEBOUNCE_MS);
    return () => clearTimeout(debounceTimeoutId);
  }, [query]);

  useEffect(() => {
    if (debouncedQuery.trim() === "") {
      setUsers([]);
      setError(null);
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    setLoading(true);
    setError(null);

    fetch(`/api/users?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Request failed with status ${res.status}`);
        }
        return res.json() as Promise<unknown>;
      })
      .then((payload) => {
        if (!isUserArray(payload)) {
          throw new Error("Received malformed user data from server");
        }
        setUsers(payload);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (err instanceof DOMException && err.name === "AbortError") {
          return;
        }
        setError(err instanceof Error ? err.message : "Failed to fetch users");
        setUsers([]);
        setLoading(false);
      });

    return () => controller.abort();
  }, [debouncedQuery]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <label>
        Sort by:{" "}
        <select
          value={sortField}
          onChange={(e) => setSortField(e.target.value as SortField)}
        >
          <option value="name">Name</option>
          <option value="email">Email</option>
        </select>
      </label>

      {loading && <p role="status">Loading...</p>}
      {error && <p role="alert">Error: {error}</p>}

      {!loading && !error && debouncedQuery.trim() !== "" && (
        <p>
          {sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}
        </p>
      )}

      <ul>
        {sortedUsers.map((user) => (
          <li key={user.id}>
            {user.name} ({user.email})
          </li>
        ))}
      </ul>
    </div>
  );
}

import Foundation
import SwiftUI

struct SearchResult: Identifiable, Decodable {
    let id: String
    let title: String
    let subtitle: String
}

private struct SearchResponse: Decodable {
    let results: [SearchResult]
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = "" {
        didSet { scheduleSearch() }
    }
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private var searchTask: Task<Void, Never>?
    private let debounceInterval: Duration
    private let session: URLSession

    init(debounceInterval: Duration = .milliseconds(300), session: URLSession = .shared) {
        self.debounceInterval = debounceInterval
        self.session = session
    }

    private func scheduleSearch() {
        searchTask?.cancel()

        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            results = []
            errorMessage = nil
            isLoading = false
            return
        }

        searchTask = Task { [weak self, debounceInterval] in
            try? await Task.sleep(for: debounceInterval)
            guard !Task.isCancelled else { return }
            await self?.performSearch(for: trimmed)
        }
    }

    private func performSearch(for trimmed: String) async {
        isLoading = true
        errorMessage = nil

        guard var components = URLComponents(string: "https://api.example.com/search") else {
            isLoading = false
            errorMessage = "Invalid search URL."
            return
        }
        components.queryItems = [URLQueryItem(name: "q", value: trimmed)]

        guard let url = components.url else {
            isLoading = false
            errorMessage = "Invalid search URL."
            return
        }

        do {
            let (data, response) = try await session.data(from: url)
            try Task.checkCancellation()

            if let httpResponse = response as? HTTPURLResponse, !(200...299).contains(httpResponse.statusCode) {
                results = []
                errorMessage = "Server returned status \(httpResponse.statusCode)."
                isLoading = false
                return
            }

            let decoded = try JSONDecoder().decode(SearchResponse.self, from: data)
            results = decoded.results
            isLoading = false
        } catch is CancellationError {
            // A newer search superseded this one; leave state as-is.
        } catch {
            if (error as? URLError)?.code == .cancelled {
                return
            }
            results = []
            errorMessage = error.localizedDescription
            isLoading = false
        }
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        NavigationStack {
            content
                .navigationTitle("Search")
                .searchable(text: $viewModel.query, prompt: "Search")
        }
    }

    @ViewBuilder
    private var content: some View {
        if viewModel.isLoading {
            ProgressView("Searching…")
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if let errorMessage = viewModel.errorMessage {
            emptyState(
                systemImage: "exclamationmark.triangle",
                title: "Something Went Wrong",
                message: errorMessage
            )
        } else if viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            emptyState(
                systemImage: "magnifyingglass",
                title: "Search",
                message: "Start typing to search."
            )
        } else if viewModel.results.isEmpty {
            emptyState(
                systemImage: "magnifyingglass",
                title: "No Results",
                message: "No results for \"\(viewModel.query)\"."
            )
        } else {
            List(viewModel.results) { result in
                VStack(alignment: .leading, spacing: 4) {
                    Text(result.title)
                        .font(.headline)
                    Text(result.subtitle)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            }
        }
    }

    private func emptyState(systemImage: String, title: String, message: String) -> some View {
        VStack(spacing: 8) {
            Image(systemName: systemImage)
                .font(.largeTitle)
                .foregroundStyle(.secondary)
            Text(title)
                .font(.headline)
            Text(message)
                .font(.subheadline)
                .foregroundStyle(.secondary)
                .multilineTextAlignment(.center)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .padding()
    }
}

import SwiftUI

struct SearchResult: Identifiable, Decodable, Equatable {
    let id: String
    let title: String
    let subtitle: String
}

private struct SearchResponse: Decodable {
    let results: [SearchResult]
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = "" {
        didSet { scheduleSearch() }
    }
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private var searchTask: Task<Void, Never>?
    private let debounceInterval: Duration
    private let session: URLSession

    init(debounceInterval: Duration = .milliseconds(300), session: URLSession = .shared) {
        self.debounceInterval = debounceInterval
        self.session = session
    }

    private func scheduleSearch() {
        searchTask?.cancel()

        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            isLoading = false
            errorMessage = nil
            results = []
            return
        }

        searchTask = Task { [debounceInterval] in
            await self.performSearch(for: trimmed, after: debounceInterval)
        }
    }

    private func performSearch(for term: String, after debounceInterval: Duration) async {
        do {
            try await Task.sleep(for: debounceInterval)

            isLoading = true
            errorMessage = nil

            var components = URLComponents(string: "https://api.example.com/search")
            components?.queryItems = [URLQueryItem(name: "q", value: term)]

            guard let url = components?.url else {
                isLoading = false
                errorMessage = "Invalid search query."
                return
            }

            let (data, response) = try await session.data(from: url)

            if let httpResponse = response as? HTTPURLResponse,
               !(200...299).contains(httpResponse.statusCode) {
                throw URLError(.badServerResponse)
            }

            let decoded = try JSONDecoder().decode(SearchResponse.self, from: data)

            results = decoded.results
            isLoading = false
        } catch {
            // A newer search may have cancelled this one before it finished; that
            // search owns the published state, so a stale task must not touch it.
            guard !Task.isCancelled else { return }
            results = []
            isLoading = false
            errorMessage = "Search failed: \(error.localizedDescription)"
        }
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel: SearchViewModel

    init(viewModel: SearchViewModel) {
        _viewModel = StateObject(wrappedValue: viewModel)
    }

    @MainActor
    init() {
