@MainActor
final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsed: TimeInterval = 0
    @Published private(set) var laps: [TimeInterval] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startDate: Date?
    private var accumulated: TimeInterval = 0

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startDate = Date()
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            Task { @MainActor in
                self?.tick()
            }
        }
    }

    func stop() {
        guard isRunning else { return }
        isRunning = false
        timer?.invalidate()
        timer = nil
        accumulated = elapsed
        startDate = nil
    }

    func reset() {
        stop()
        elapsed = 0
        accumulated = 0
        laps = []
    }

    func lap() {
        guard isRunning else { return }
        laps.append(elapsed)
    }

    private func tick() {
        guard let startDate else { return }
        elapsed = accumulated + Date().timeIntervalSince(startDate)
    }
}

enum StopwatchFormatter {
    static func format(_ time: TimeInterval) -> String {
        let totalCentiseconds = Int((time * 100).rounded())
        let minutes = totalCentiseconds / 6000
        let seconds = (totalCentiseconds / 100) % 60
        let centiseconds = totalCentiseconds % 100
        return String(format: "%02d:%02d.%02d", minutes, seconds, centiseconds)
    }
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 20) {
            Text(StopwatchFormatter.format(viewModel.elapsed))
                .font(.system(size: 54, weight: .medium, design: .monospaced))
                .monospacedDigit()

            HStack(spacing: 16) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    viewModel.isRunning ? viewModel.stop() : viewModel.start()
                }
                Button("Lap") {
                    viewModel.lap()
                }
                .disabled(!viewModel.isRunning)
                Button("Reset") {
                    viewModel.reset()
                }
                .disabled(viewModel.isRunning && viewModel.elapsed == 0)
            }
            .buttonStyle(.bordered)

            List {
                ForEach(Array(viewModel.laps.enumerated().reversed()), id: \.offset) { index, lap in
                    HStack {
                        Text("Lap \(index + 1)")
                        Spacer()
                        Text(StopwatchFormatter.format(lap))
                            .monospacedDigit()
                        Text(splitDescription(index: index))
                            .monospacedDigit()
                            .foregroundStyle(.secondary)
                    }
                }
            }
        }
        .padding()
        .frame(minWidth: 320, minHeight: 400)
    }

    private func splitDescription(index: Int) -> String {
        let lap = viewModel.laps[index]
        let previous = index > 0 ? viewModel.laps[index - 1] : 0
        return "+" + StopwatchFormatter.format(lap - previous)
    }
}

import Foundation
import SwiftUI

struct Lap: Identifiable {
    let id = UUID()
    let number: Int
    let split: TimeInterval
}

final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsed: TimeInterval = 0
    @Published private(set) var laps: [Lap] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startDate: Date?
    private var accumulated: TimeInterval = 0
    private var lastLapTotal: TimeInterval = 0

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startDate = Date()
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            self?.tick()
        }
    }

    func stop() {
        guard isRunning else { return }
        if let startDate {
            accumulated += Date().timeIntervalSince(startDate)
        }
        startDate = nil
        isRunning = false
        timer?.invalidate()
        timer = nil
    }

    func reset() {
        stop()
        elapsed = 0
        accumulated = 0
        laps = []
        lastLapTotal = 0
    }

    func lap() {
        guard isRunning else { return }
        let split = elapsed - lastLapTotal
        lastLapTotal = elapsed
        laps.append(Lap(number: laps.count + 1, split: split))
    }

    private func tick() {
        guard let startDate else { return }
        elapsed = accumulated + Date().timeIntervalSince(startDate)
    }
}

