import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  error: string | null;
}

const MAX_CONCURRENT_REQUESTS = 4;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

async function fetchUser(id: string): Promise<User> {
  const response = await fetch(`/api/users/${id}`);
  if (!response.ok) {
    throw new Error(`Failed to load user ${id}: ${response.status}`);
  }
  const data: unknown = await response.json();
  if (!isUser(data)) {
    throw new Error(`Received malformed user payload for ${id}`);
  }
  return data;
}

async function fetchUsersWithLimit(ids: string[], limit: number): Promise<User[]> {
  const results: User[] = new Array(ids.length);
  let nextIndex = 0;

  async function worker() {
    while (true) {
      const currentIndex = nextIndex;
      nextIndex += 1;
      if (currentIndex >= ids.length) return;
      results[currentIndex] = await fetchUser(ids[currentIndex]);
    }
  }

  const workers = Array.from({ length: Math.min(limit, ids.length) }, () => worker());
  await Promise.all(workers);
  return results;
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [loading, setLoading] = useState(ids.length > 0);
  const [error, setError] = useState<string | null>(null);

  const idsKey = ids.join(",");

  useEffect(() => {
    if (ids.length === 0) {
      setProfiles({});
      setLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchUsersWithLimit(ids, MAX_CONCURRENT_REQUESTS)
      .then((users) => {
        if (cancelled) return;
        const byId: Record<string, User> = {};
        for (const user of users) {
          byId[user.id] = user;
        }
        setProfiles(byId);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to load user profiles");
      })
      .finally(() => {
        if (cancelled) return;
        setLoading(false);
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [idsKey]);

  return { profiles, loading, error };
}

import { useState } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const hasChanges = displayName !== user.displayName || bio !== user.bio;

  const handleReset = () => {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  };

  const handleSave = async () => {
    if (!hasChanges || isSaving) return;
    setIsSaving(true);
    setError(null);
    try {
      await onSave({ ...user, displayName, bio });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save profile");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="profile-editor">
      <img src={user.avatarUrl} alt={`${user.displayName}'s avatar`} className="profile-editor__avatar" />

      <label className="profile-editor__field">
        <span>Display name</span>
        <input
          type="text"
          value={displayName}
          onChange={(e) => setDisplayName(e.target.value)}
          disabled={isSaving}
        />
      </label>

      <label className="profile-editor__field">
        <span>Bio</span>
        <textarea
          value={bio}
          onChange={(e) => setBio(e.target.value)}
          disabled={isSaving}
        />
      </label>

      <div className="profile-editor__status">
        {hasChanges ? "Unsaved changes" : "No changes"}
      </div>

      {error && <div className="profile-editor__error">{error}</div>}

      <div className="profile-editor__actions">
        <button type="button" onClick={handleReset} disabled={!hasChanges || isSaving}>
          Reset
        </button>
        <button type="button" onClick={handleSave} disabled={!hasChanges || isSaving}>
          {isSaving ? "Saving…" : "Save"}
        </button>
      </div>
    </div>
  );
}

export default ProfileEditor;

import Foundation
import SwiftUI

/// Persists user preferences to `UserDefaults` and stays in sync when another
/// part of the app (or another process sharing the same defaults) changes them.
final class SettingsStore: ObservableObject {
    enum Theme: String, CaseIterable, Identifiable {
        case system
        case light
        case dark

        var id: String { rawValue }

        var label: String {
            switch self {
            case .system: return "System"
            case .light: return "Light"
            case .dark: return "Dark"
            }
        }
    }

    private enum Keys {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    static let defaultRefreshInterval: TimeInterval = 60

    @Published var displayName: String {
        didSet { persist(displayName, forKey: Keys.displayName) }
    }

    @Published var theme: Theme {
        didSet { persist(theme.rawValue, forKey: Keys.theme) }
    }

    @Published var notificationsEnabled: Bool {
        didSet { persist(notificationsEnabled, forKey: Keys.notificationsEnabled) }
    }

    @Published var refreshInterval: TimeInterval {
        didSet { persist(refreshInterval, forKey: Keys.refreshInterval) }
    }

    private let defaults: UserDefaults
    private var isApplyingExternalChange = false
    private var observer: NSObjectProtocol?

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        self.displayName = defaults.string(forKey: Keys.displayName) ?? ""
        self.theme = Theme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        self.notificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        self.refreshInterval = defaults.object(forKey: Keys.refreshInterval) as? TimeInterval ?? Self.defaultRefreshInterval

        observer = NotificationCenter.default.addObserver(
            forName: UserDefaults.didChangeNotification,
            object: defaults,
            queue: .main
        ) { [weak self] _ in
            self?.reloadFromDefaults()
        }
    }

    deinit {
        if let observer {
            NotificationCenter.default.removeObserver(observer)
        }
    }

    /// Re-reads every value from `UserDefaults`, guarding against re-writing
    /// the values we just read (which would otherwise re-trigger this observer).
    private func reloadFromDefaults() {
        isApplyingExternalChange = true
        defer { isApplyingExternalChange = false }

        let newDisplayName = defaults.string(forKey: Keys.displayName) ?? ""
        if newDisplayName != displayName {
            displayName = newDisplayName
        }

        let newTheme = Theme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        if newTheme != theme {
            theme = newTheme
        }

        let newNotificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        if newNotificationsEnabled != notificationsEnabled {
            notificationsEnabled = newNotificationsEnabled
        }

        let newRefreshInterval = defaults.object(forKey: Keys.refreshInterval) as? TimeInterval ?? Self.defaultRefreshInterval
        if newRefreshInterval != refreshInterval {
            refreshInterval = newRefreshInterval
        }
    }

    private func persist<Value>(_ value: Value, forKey key: String) {
        guard !isApplyingExternalChange else { return }
        defaults.set(value, forKey: key)
    }
}

struct SettingsScreen: View {
    @ObservedObject var store: SettingsStore

    private static let refreshIntervalOptions: [TimeInterval] = [15, 30, 60, 300, 900]

    var body: some View {
        Form {
            Section("Profile") {
                TextField("Display Name", text: $store.displayName)
                    #if os(iOS)
                    .textInputAutocapitalization(.words)
                    #endif
            }

            Section("Appearance") {
                Picker("Theme", selection: $store.theme) {
                    ForEach(SettingsStore.Theme.allCases) { theme in
                        Text(theme.label).tag(theme)
                    }
                }
                .pickerStyle(.segmented)
            }

            Section("Notifications") {
                Toggle("Enable Notifications", isOn: $store.notificationsEnabled)
            }

            Section("Data") {
                Picker("Refresh Interval", selection: $store.refreshInterval) {
                    ForEach(Self.refreshIntervalOptions, id: \.self) { interval in
                        Text(Self.label(for: interval)).tag(interval)
                    }
                }
            }
        }
        .navigationTitle("Settings")
    }

    private static func label(for interval: TimeInterval) -> String {
        if interval < 60 {
            return "\(Int(interval))s"
        }
        return "\(Int(interval / 60))m"
    }
}

