import Foundation
import SwiftUI
import Combine

struct Lap: Identifiable {
    let id: Int
    let splitTime: TimeInterval
    let totalTime: TimeInterval
}

final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsed: TimeInterval = 0
    @Published private(set) var laps: [Lap] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startDate: Date?

    var formattedElapsed: String {
        Self.format(elapsed)
    }

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startDate = Date().addingTimeInterval(-elapsed)
        timer = Timer.scheduledTimer(withTimeInterval: 0.03, repeats: true) { [weak self] _ in
            self?.tick()
        }
    }

    func stop() {
        guard isRunning else { return }
        isRunning = false
        timer?.invalidate()
        timer = nil
    }

    func reset() {
        stop()
        elapsed = 0
        laps = []
        startDate = nil
    }

    func lap() {
        guard isRunning else { return }
        let previousTotal = laps.last?.totalTime ?? 0
        let split = elapsed - previousTotal
        laps.append(Lap(id: laps.count + 1, splitTime: split, totalTime: elapsed))
    }

    private func tick() {
        guard let startDate else { return }
        elapsed = Date().timeIntervalSince(startDate)
    }

    static func format(_ time: TimeInterval) -> String {
        let minutes = Int(time) / 60
        let seconds = Int(time) % 60
        let hundredths = Int((time.truncatingRemainder(dividingBy: 1)) * 100)
        return String(format: "%02d:%02d.%02d", minutes, seconds, hundredths)
    }
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 24) {
            Text(viewModel.formattedElapsed)
                .font(.system(size: 56, weight: .light, design: .monospaced))
                .monospacedDigit()

            HStack(spacing: 16) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    viewModel.isRunning ? viewModel.stop() : viewModel.start()
                }
                .buttonStyle(.borderedProminent)
                .tint(viewModel.isRunning ? .red : .green)

                Button("Lap") {
                    viewModel.lap()
                }
                .buttonStyle(.bordered)
                .disabled(!viewModel.isRunning)

                Button("Reset") {
                    viewModel.reset()
                }
                .buttonStyle(.bordered)
                .disabled(viewModel.isRunning || viewModel.elapsed == 0)
            }

            List {
                ForEach(viewModel.laps.reversed()) { lap in
                    HStack {
                        Text("Lap \(lap.id)")
                            .foregroundStyle(.secondary)
                        Spacer()
                        Text(StopwatchViewModel.format(lap.splitTime))
                            .monospacedDigit()
                        Spacer()
                        Text(StopwatchViewModel.format(lap.totalTime))
                            .monospacedDigit()
                            .foregroundStyle(.secondary)
                    }
                }
            }
        }
        .padding()
    }
}

