/// Shared in-memory cache so scrolling back through the grid doesn't re-download thumbnails.
public actor ThumbnailCache {
    public static let shared = ThumbnailCache()

    private let storage = NSCache<NSURL, PlatformImage>()

    private init() {}

    public func image(for url: URL) -> PlatformImage? {
        storage.object(forKey: url as NSURL)
    }

    public func insert(_ image: PlatformImage, for url: URL) {
        storage.setObject(image, forKey: url as NSURL)
    }
}

@MainActor
final class ThumbnailLoader: ObservableObject {
    @Published private(set) var image: PlatformImage?

    private let url: URL

    init(url: URL) {
        self.url = url
    }

    func load() async {
        if let cached = await ThumbnailCache.shared.image(for: url) {
            image = cached
            return
        }
        guard let (data, _) = try? await URLSession.shared.data(from: url),
              let downloaded = PlatformImage(data: data) else {
            return
        }
        await ThumbnailCache.shared.insert(downloaded, for: url)
        image = downloaded
    }
}

