/// A photo to display in the grid: its remote thumbnail URL and when it was downloaded.
struct Photo: Identifiable, Hashable {
    let id: UUID
    let url: URL
    let downloadDate: Date

    init(id: UUID = UUID(), url: URL, downloadDate: Date) {
        self.id = id
        self.url = url
        self.downloadDate = downloadDate
    }
}

/// Process-wide cache of downloaded thumbnails, keyed by URL, so scrolling back through
/// the grid doesn't re-download images that are already in memory.
final class ImageCache {
    static let shared = ImageCache()

    private let cache = NSCache<NSURL, NSImage>()

    private init() {}

    func image(for url: URL) -> NSImage? {
        cache.object(forKey: url as NSURL)
    }

    func insert(_ image: NSImage, for url: URL) {
        cache.setObject(image, forKey: url as NSURL)
    }
}

/// Downloads a thumbnail for a URL, consulting and populating the shared `ImageCache`.
enum ThumbnailLoader {
    static func load(url: URL) async throws -> NSImage {
        if let cached = ImageCache.shared.image(for: url) {
            return cached
        }
        let (data, _) = try await URLSession.shared.data(from: url)
        guard let image = NSImage(data: data) else {
            throw URLError(.cannotDecodeContentData)
        }
        ImageCache.shared.insert(image, for: url)
        return image
    }
}

private let relativeDateFormatter: RelativeDateTimeFormatter = {
    let formatter = RelativeDateTimeFormatter()
    formatter.unitsStyle = .full
    return formatter
}()

/// A single grid cell: a thumbnail that loads asynchronously with a placeholder,
