    let photo: Photo

    @State private var image: NSImage?
    @State private var failed = false

    var body: some View {
        VStack(spacing: 4) {
            ZStack {
                RoundedRectangle(cornerRadius: 8)
                    .fill(Color.gray.opacity(0.2))
                if let image {
                    Image(nsImage: image)
                        .resizable()
                        .aspectRatio(contentMode: .fill)
                        .clipShape(RoundedRectangle(cornerRadius: 8))
                } else if failed {
                    Image(systemName: "exclamationmark.triangle")
                        .foregroundStyle(.secondary)
                } else {
                    ProgressView()
                }
            }
            .aspectRatio(1, contentMode: .fit)

            Text(relativeDateFormatter.localizedString(for: photo.downloadDate, relativeTo: Date()))
                .font(.caption)
                .foregroundStyle(.secondary)
                .lineLimit(1)
        }
        .task(id: photo.url) {
            guard image == nil else { return }
            failed = false
            do {
                image = try await ThumbnailLoader.load(url: photo.url)
            } catch {
                failed = true
            }
        }
    }
}

