// MARK: - Modern async/await wrappers

enum LegacyBridgeError: Error {
    case uploadAlreadyInProgress
}

func geocode(_ address: String) async throws -> (Double, Double) {
    let geocoder = LegacyGeocoder()
    return try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { continuation in
            geocoder.geocode(address) { result in
                continuation.resume(with: result)
            }
        }
    } onCancel: {
        // LegacyGeocoder has no cancellation hook; the continuation still
        // resumes once its callback eventually fires.
    }
}

/// Bridges `LegacyUploader` to async/await, exposing progress as an `AsyncStream`
/// alongside the awaitable `upload(file:)` call. Only one upload may be in
/// flight per instance; a concurrent call throws rather than clobbering state.
final class LegacyUploadBridge {
    private let uploader = LegacyUploader()
    private let lock = NSLock()
    private var progressContinuation: AsyncStream<Double>.Continuation?
    private var isUploading = false

    private(set) lazy var progress: AsyncStream<Double> = {
        AsyncStream { continuation in
            self.progressContinuation = continuation
            continuation.onTermination = { [weak self] _ in
                self?.clearProgressContinuation()
            }
        }
    }()

    func upload(file: URL) async throws {
        try beginUpload()
        _ = progress // ensure the continuation exists before starting
        defer { endUpload() }

        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                uploader.onProgress = { [weak self] value in
                    self?.emitProgress(value)
                }
                uploader.onFinish = { [weak self] error in
                    self?.finishProgress()
                    if let error {
                        continuation.resume(throwing: error)
                    } else {
                        continuation.resume(returning: ())
                    }
                }
                uploader.start(file: file)
            }
        } onCancel: {
            // LegacyUploader has no cancellation hook; the transfer keeps
            // running and the continuation resumes when onFinish fires.
        }
    }

    private func beginUpload() throws {
        lock.lock()
        defer { lock.unlock() }
        guard !isUploading else {
            throw LegacyBridgeError.uploadAlreadyInProgress
        }
        isUploading = true
    }

    private func endUpload() {
        lock.lock()
        defer { lock.unlock() }
        isUploading = false
    }

    private func emitProgress(_ value: Double) {
        lock.lock()
        let continuation = progressContinuation
        lock.unlock()
        continuation?.yield(value)
    }

    private func finishProgress() {
        lock.lock()
        let continuation = progressContinuation
        lock.unlock()
        continuation?.finish()
    }

    private func clearProgressContinuation() {
        lock.lock()
        defer { lock.unlock() }
        progressContinuation = nil
    }
}

import { useEffect, useMemo, useState } from "react";
import type { ChangeEvent, KeyboardEvent } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function loadTodos(): Todo[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (item): item is Todo =>
        typeof item === "object" &&
        item !== null &&
        typeof item.id === "string" &&
        typeof item.text === "string" &&
        typeof item.done === "boolean"
    );
  } catch {
    return [];
  }
}

function createId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const [newText, setNewText] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  // Read localStorage only after mount so the first render is identical
  // whether or not persisted data exists (avoids hydration mismatches).
  useEffect(() => {
    setTodos(loadTodos());
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (!isLoaded) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }, [todos, isLoaded]);

  const remainingCount = useMemo(
    () => todos.filter((todo) => !todo.done).length,
    [todos]
  );

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function addTodo() {
    const text = newText.trim();
    if (!text) return;
    setTodos((prev) => [...prev, { id: createId(), text, done: false }]);
    setNewText("");
  }

  function handleNewTextKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Enter") {
      addTodo();
    }
  }

  function toggleDone(id: string) {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo
      )
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEditing(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function cancelEditing() {
    setEditingId(null);
    setEditingText("");
  }

  function commitEditing() {
    if (editingId === null) return;
    const text = editingText.trim();
    if (!text) {
      deleteTodo(editingId);
    } else {
      setTodos((prev) =>
        prev.map((todo) =>
          todo.id === editingId ? { ...todo, text } : todo
        )
      );
    }
    setEditingId(null);
    setEditingText("");
  }

  function handleEditKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Enter") {
      commitEditing();
    } else if (event.key === "Escape") {
      cancelEditing();
    }
  }

  function moveUp(id: string) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      if (index <= 0) return prev;
      const next = [...prev];
      const [item] = next.splice(index, 1);
      next.splice(index - 1, 0, item);
      return next;
    });
  }

  function moveDown(id: string) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      if (index === -1 || index >= prev.length - 1) return prev;
      const next = [...prev];
      const [item] = next.splice(index, 1);
      next.splice(index + 1, 0, item);
      return next;
    });
  }

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <div className="todo-add">
        <input
          type="text"
          value={newText}
          placeholder="Add a new todo"
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setNewText(event.target.value)
          }
          onKeyDown={handleNewTextKeyDown}
        />
        <button type="button" onClick={addTodo}>
          Add
        </button>
      </div>

      <div className="todo-filters">
        <button
          type="button"
          disabled={filter === "all"}
          onClick={() => setFilter("all")}
        >
          All
        </button>
        <button
          type="button"
          disabled={filter === "active"}
          onClick={() => setFilter("active")}
        >
          Active
        </button>
        <button
          type="button"
          disabled={filter === "done"}
          onClick={() => setFilter("done")}
        >
          Done
        </button>
      </div>

      <ul className="todo-list">
        {visibleTodos.map((todo) => {
          const originalIndex = todos.findIndex((item) => item.id === todo.id);
          const isEditing = editingId === todo.id;
          return (
            <li key={todo.id} className="todo-item">
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
              />

              {isEditing ? (
                <input
                  type="text"
                  className="todo-edit-input"
                  value={editingText}
                  autoFocus
                  onChange={(event: ChangeEvent<HTMLInputElement>) =>
                    setEditingText(event.target.value)
                  }
                  onKeyDown={handleEditKeyDown}
                  onBlur={commitEditing}
                />
              ) : (
                <span
                  className={todo.done ? "todo-text todo-done" : "todo-text"}
                  onDoubleClick={() => startEditing(todo)}
                >
                  {todo.text}
                </span>
              )}

              <button type="button" onClick={() => startEditing(todo)}>
                Edit
              </button>
              <button
                type="button"
                disabled={originalIndex === 0}
                onClick={() => moveUp(todo.id)}
              >
                ↑
              </button>
              <button
                type="button"
                disabled={originalIndex === todos.length - 1}
                onClick={() => moveDown(todo.id)}
              >
                ↓
              </button>
              <button type="button" onClick={() => deleteTodo(todo.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>

      <div className="todo-count">
        {remainingCount} item{remainingCount === 1 ? "" : "s"} remaining
      </div>
    </div>
  );
}

import Foundation
import SwiftUI

struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatConnection: NSObject, ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []

    private let url = URL(string: "wss://chat.example.com/room")!
    private var session: URLSession!
    private var task: URLSessionWebSocketTask?
    private var reconnectDelay: TimeInterval = 1
    private var isConnecting = false

    override init() {
        super.init()
        session = URLSession(configuration: .default, delegate: self, delegateQueue: nil)
    }

    func connect() {
        guard !isConnecting else { return }
        isConnecting = true
        let task = session.webSocketTask(with: url)
        self.task = task
        task.resume()
        listen(on: task)
    }

    func send(text: String) {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let task else { return }
        let message = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(message) else { return }
        task.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                self?.scheduleReconnect()
            }
        }
    }

    private func listen(on task: URLSessionWebSocketTask) {
        task.receive { [weak self] result in
            guard let self else { return }
            Task { @MainActor in
                switch result {
                case .success(let message):
                    self.handle(message: message)
                    self.listen(on: task)
                case .failure:
                    self.scheduleReconnect()
                }
            }
        }
    }

    private func handle(message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let d):
            data = d
        case .string(let s):
            data = Data(s.utf8)
        @unknown default:
            return
        }
        guard let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
    }

    private func scheduleReconnect() {
        task = nil
        isConnecting = false
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, 30)
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            self?.connect()
        }
    }
}

extension ChatConnection: URLSessionWebSocketDelegate {
    nonisolated func urlSession(
        _ session: URLSession,
        webSocketTask: URLSessionWebSocketTask,
        didOpenWithProtocol protocol: String?
    ) {
        Task { @MainActor [weak self] in
            self?.reconnectDelay = 1
        }
    }

    nonisolated func urlSession(
        _ session: URLSession,
        webSocketTask: URLSessionWebSocketTask,
        didCloseWith closeCode: URLSessionWebSocketTask.CloseCode,
        reason: Data?
    ) {
        Task { @MainActor [weak self] in
            self?.scheduleReconnect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var connection = ChatConnection()
    @State private var draft = ""

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(connection.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .padding(.horizontal)
                        }
                    }
                    .padding(.vertical, 8)
                }
                .onChange(of: connection.messages) { newMessages in
