import SwiftUI

/// A photo to display in the grid: its remote thumbnail URL and when it was downloaded.
public struct Photo: Identifiable, Hashable {
    public let id: URL
    public let url: URL
    public let downloadDate: Date

    public init(url: URL, downloadDate: Date) {
        self.id = url
        self.url = url
        self.downloadDate = downloadDate
    }
}

/// Shared in-memory cache so scrolling the grid back and forth doesn't re-download thumbnails.
public actor ImageCache {
    public static let shared = ImageCache()

    private var storage: [URL: PlatformImage] = [:]

    private init() {}

    func image(for url: URL) -> PlatformImage? {
        storage[url]
    }

    func insert(_ image: PlatformImage, for url: URL) {
        storage[url] = image
    }
}

#if canImport(UIKit)
import UIKit
public typealias PlatformImage = UIImage
#elseif canImport(AppKit)
import AppKit
public typealias PlatformImage = NSImage
#endif

private extension Image {
    init(platformImage: PlatformImage) {
        #if canImport(UIKit)
        self.init(uiImage: platformImage)
        #elseif canImport(AppKit)
        self.init(nsImage: platformImage)
        #endif
    }
}

@MainActor
private final class ThumbnailLoader: ObservableObject {
    @Published var image: PlatformImage?

    func load(from url: URL) async {
        if let cached = await ImageCache.shared.image(for: url) {
            image = cached
            return
        }
        guard let (data, _) = try? await URLSession.shared.data(from: url),
              let downloaded = PlatformImage(data: data) else {
            return
        }
        await ImageCache.shared.insert(downloaded, for: url)
        image = downloaded
    }
}

private let relativeDateFormatter: RelativeDateTimeFormatter = {
    let formatter = RelativeDateTimeFormatter()
    formatter.unitsStyle = .full
    return formatter
}()

private struct ThumbnailCell: View {
    let photo: Photo
    @StateObject private var loader = ThumbnailLoader()

    var body: some View {
        VStack(spacing: 4) {
            ZStack {
                Rectangle()
                    .fill(Color.secondary.opacity(0.2))
                if let image = loader.image {
                    Image(platformImage: image)
                        .resizable()
                        .aspectRatio(contentMode: .fill)
                } else {
                    ProgressView()
                }
            }
            .aspectRatio(1, contentMode: .fit)
            .clipped()

            Text(relativeDateFormatter.localizedString(for: photo.downloadDate, relativeTo: Date()))
                .font(.caption)
                .foregroundStyle(.secondary)
                .lineLimit(1)
        }
        .task(id: photo.url) {
            await loader.load(from: photo.url)
        }
    }
}

/// A grid of photo thumbnails, downloaded asynchronously and cached in memory.
public struct ThumbnailGrid: View {
    private let photos: [Photo]
    private let columns: [GridItem]

    public init(photos: [Photo], minCellWidth: CGFloat = 100) {
        self.photos = photos
        self.columns = [GridItem(.adaptive(minimum: minCellWidth), spacing: 8)]
    }

    public var body: some View {
        ScrollView {
            LazyVGrid(columns: columns, spacing: 8) {
                ForEach(photos) { photo in
                    ThumbnailCell(photo: photo)
                }
            }
            .padding(8)
        }
    }
}

