import { useState } from "react";
import type { FormEvent } from "react";

interface FormValues {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<keyof FormValues, string>>;

interface SignupResponse {
  id: string;
}

interface SignupErrorResponse {
  errors?: FieldErrors;
}

const INITIAL_VALUES: FormValues = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function isFieldErrors(value: unknown): value is FieldErrors {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  return Object.values(value).every((message) => typeof message === "string");
}

function parseSignupErrorResponse(payload: unknown): SignupErrorResponse {
  if (typeof payload !== "object" || payload === null) {
    return {};
  }
  const { errors } = payload as { errors?: unknown };
  return isFieldErrors(errors) ? { errors } : {};
}

function parseSignupResponse(payload: unknown): SignupResponse | null {
  if (typeof payload !== "object" || payload === null) {
    return null;
  }
  const { id } = payload as { id?: unknown };
  return typeof id === "string" ? { id } : null;
}

function validate(values: FormValues): FieldErrors {
  const errors: FieldErrors = {};

  if (!values.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!values.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(values.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!values.password) {
    errors.password = "Password is required.";
  } else if (values.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!values.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (values.confirmPassword !== values.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!values.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

export default function SignupForm() {
  const [values, setValues] = useState<FormValues>(INITIAL_VALUES);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [accountId, setAccountId] = useState<string | null>(null);
  const [submitError, setSubmitError] = useState<string | null>(null);

  function updateField<K extends keyof FormValues>(field: K, value: FormValues[K]) {
    setValues((prev) => ({ ...prev, [field]: value }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitError(null);
    setAccountId(null);

    const validationErrors = validate(values);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) {
      return;
    }

    setSubmitting(true);
    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: values.name,
          email: values.email,
          password: values.password,
          acceptTerms: values.acceptTerms,
        }),
      });

      const rawBody: unknown = await response.json().catch(() => null);

      if (!response.ok) {
        const { errors: serverErrors } = parseSignupErrorResponse(rawBody);
        if (serverErrors) {
          setErrors(serverErrors);
        } else {
          setSubmitError("Signup failed. Please try again.");
        }
        return;
      }

      const signupResult = parseSignupResponse(rawBody);
      if (!signupResult) {
        setSubmitError("Unexpected response from server. Please try again.");
        return;
      }

      setAccountId(signupResult.id);
      setValues(INITIAL_VALUES);
      setErrors({});
    } catch {
      setSubmitError("Network error. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <h1>Create an account</h1>

      {accountId && (
        <p role="status">Account created successfully! Your account id is {accountId}.</p>
      )}
      {submitError && <p role="alert">{submitError}</p>}

      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          type="text"
          value={values.name}
          onChange={(e) => updateField("name", e.target.value)}
          aria-invalid={Boolean(errors.name)}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && <p id="name-error">{errors.name}</p>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={values.email}
          onChange={(e) => updateField("email", e.target.value)}
          aria-invalid={Boolean(errors.email)}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && <p id="email-error">{errors.email}</p>}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={values.password}
          onChange={(e) => updateField("password", e.target.value)}
          aria-invalid={Boolean(errors.password)}
          aria-describedby={errors.password ? "password-error" : undefined}
        />
        {errors.password && <p id="password-error">{errors.password}</p>}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm password</label>
        <input
          id="confirmPassword"
          type="password"
          value={values.confirmPassword}
          onChange={(e) => updateField("confirmPassword", e.target.value)}
          aria-invalid={Boolean(errors.confirmPassword)}
          aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
        />
        {errors.confirmPassword && <p id="confirmPassword-error">{errors.confirmPassword}</p>}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            type="checkbox"
            checked={values.acceptTerms}
            onChange={(e) => updateField("acceptTerms", e.target.checked)}
            aria-invalid={Boolean(errors.acceptTerms)}
            aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && <p id="acceptTerms-error">{errors.acceptTerms}</p>}
      </div>

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up..." : "Sign up"}
      </button>
    </form>
  );
}

import { useEffect, useMemo, useState } from "react";
import type { ChangeEvent, FormEvent } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board-items";

function loadTodos(): Todo[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (item): item is Todo =>
        typeof item === "object" &&
        item !== null &&
        typeof item.id === "string" &&
        typeof item.text === "string" &&
        typeof item.done === "boolean",
    );
  } catch {
    return [];
  }
}

function createId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(() => loadTodos());
  const [newText, setNewText] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }, [todos]);

  const remainingCount = useMemo(
    () => todos.filter((todo) => !todo.done).length,
    [todos],
  );

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function handleAdd(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const text = newText.trim();
    if (!text) return;
    setTodos((prev) => [...prev, { id: createId(), text, done: false }]);
    setNewText("");
  }

  function handleToggle(id: string) {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo,
      ),
    );
  }

  function handleDelete(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEditing(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function cancelEditing() {
    setEditingId(null);
    setEditingText("");
  }

  function commitEditing(id: string) {
    const text = editingText.trim();
    setTodos((prev) =>
      prev.map((todo) => (todo.id === id ? { ...todo, text: text || todo.text } : todo)),
    );
    setEditingId(null);
    setEditingText("");
  }

  function moveUp(index: number) {
    if (index <= 0) return;
    setTodos((prev) => {
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
  }

  function moveDown(index: number) {
    setTodos((prev) => {
      if (index >= prev.length - 1) return prev;
      const next = [...prev];
      [next[index], next[index + 1]] = [next[index + 1], next[index]];
      return next;
    });
  }

  return (
    <div>
      <h1>Todo Board</h1>

      <form onSubmit={handleAdd}>
        <input
          type="text"
          value={newText}
          placeholder="Add a new task"
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setNewText(event.target.value)
          }
        />
        <button type="submit">Add</button>
      </form>

      <div role="group" aria-label="Filter todos">
        {(["all", "active", "done"] as Filter[]).map((option) => (
          <button
            key={option}
            type="button"
            onClick={() => setFilter(option)}
            aria-pressed={filter === option}
            disabled={filter === option}
          >
            {option}
          </button>
        ))}
      </div>

      <p>{remainingCount} item(s) remaining</p>

      <ul>
        {visibleTodos.map((todo) => {
          const index = todos.findIndex((item) => item.id === todo.id);
          const isEditing = editingId === todo.id;

          return (
            <li key={todo.id}>
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => handleToggle(todo.id)}
                aria-label={`Mark "${todo.text}" as done`}
              />

              {isEditing ? (
                <>
                  <input
                    type="text"
                    value={editingText}
                    autoFocus
                    onChange={(event: ChangeEvent<HTMLInputElement>) =>
                      setEditingText(event.target.value)
                    }
                    onKeyDown={(event) => {
                      if (event.key === "Enter") commitEditing(todo.id);
                      if (event.key === "Escape") cancelEditing();
                    }}
                  />
                  <button type="button" onClick={() => commitEditing(todo.id)}>
                    Save
                  </button>
                  <button type="button" onClick={cancelEditing}>
                    Cancel
                  </button>
                </>
              ) : (
                <>
                  <span
                    style={{
                      textDecoration: todo.done ? "line-through" : "none",
                    }}
                  >
                    {todo.text}
                  </span>
                  <button type="button" onClick={() => startEditing(todo)}>
                    Edit
                  </button>
                </>
              )}

              <button
                type="button"
                onClick={() => moveUp(index)}
                disabled={index <= 0}
                aria-label={`Move "${todo.text}" up`}
              >
                ↑
              </button>
              <button
                type="button"
                onClick={() => moveDown(index)}
                disabled={index >= todos.length - 1}
                aria-label={`Move "${todo.text}" down`}
              >
                ↓
              </button>
              <button type="button" onClick={() => handleDelete(todo.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

