    setEditingText(todo.text);
  }

  function commitEditing() {
    const text = editingText.trim();
    if (editingId && text) {
      setTodos((prev) =>
        prev.map((t) => (t.id === editingId ? { ...t, text } : t))
      );
    }
    setEditingId(null);
    setEditingText("");
  }

  function cancelEditing() {
    setEditingId(null);
    setEditingText("");
  }

  function moveUp(index: number) {
    if (index <= 0) return;
    setTodos((prev) => {
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
  }

  function moveDown(index: number) {
    setTodos((prev) => {
      if (index >= prev.length - 1) return prev;
      const next = [...prev];
      [next[index], next[index + 1]] = [next[index + 1], next[index]];
      return next;
    });
  }

  const filteredTodos = todos.filter((t) => {
    if (filter === "active") return !t.done;
    if (filter === "done") return t.done;
    return true;
  });

  const remainingCount = todos.filter((t) => !t.done).length;

  return (
    <div>
      <h1>Todo Board</h1>

      <form onSubmit={addTodo}>
        <input
          type="text"
          value={newText}
          onChange={(e) => setNewText(e.target.value)}
          placeholder="Add a new todo"
          aria-label="New todo text"
        />
        <button type="submit">Add</button>
      </form>

      <div role="group" aria-label="Filter todos">
        <button
          type="button"
          disabled={filter === "all"}
          onClick={() => setFilter("all")}
        >
          All
        </button>
        <button
          type="button"
          disabled={filter === "active"}
          onClick={() => setFilter("active")}
        >
          Active
        </button>
        <button
          type="button"
          disabled={filter === "done"}
          onClick={() => setFilter("done")}
        >
          Done
        </button>
      </div>

      <p>{remainingCount} item(s) remaining</p>

      <ul>
        {filteredTodos.map((todo) => {
          const index = todos.findIndex((t) => t.id === todo.id);
          const isEditing = editingId === todo.id;

          return (
            <li key={todo.id}>
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
                aria-label={`Mark "${todo.text}" as ${
                  todo.done ? "active" : "done"
                }`}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(e) => setEditingText(e.target.value)}
                  onBlur={commitEditing}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      e.preventDefault();
                      commitEditing();
                    } else if (e.key === "Escape") {
                      cancelEditing();
                    }
                  }}
                />
              ) : (
                <span
                  onDoubleClick={() => startEditing(todo)}
                  style={{
                    textDecoration: todo.done ? "line-through" : "none",
                  }}
                >
                  {todo.text}
                </span>
              )}

              {!isEditing && (
                <button type="button" onClick={() => startEditing(todo)}>
                  Edit
                </button>
              )}
              <button
                type="button"
                onClick={() => moveUp(index)}
                disabled={index <= 0}
                aria-label={`Move "${todo.text}" up`}
              >
                ↑
              </button>
              <button
                type="button"
                onClick={() => moveDown(index)}
                disabled={index >= todos.length - 1}
                aria-label={`Move "${todo.text}" down`}
              >
                ↓
              </button>
              <button type="button" onClick={() => deleteTodo(todo.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

interface ChatRoomProps {
  roomId: string;
}

const RECONNECT_DELAY_MS = 2000;

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.author === "string" &&
    typeof candidate.text === "string" &&
    typeof candidate.sentAt === "string"
  );
}

export default function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [isReconnecting, setIsReconnecting] = useState(false);

  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isUnmountedRef = useRef(false);
  const messagesEndRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    setMessages([]);
    isUnmountedRef.current = false;

    let socket: WebSocket | null = null;

    const connect = () => {
      if (isUnmountedRef.current) return;

      socket = new WebSocket(`wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`);
      socketRef.current = socket;

      socket.onopen = () => {
        setIsReconnecting(false);
      };

      socket.onmessage = (event) => {
        let parsed: unknown;
        try {
          parsed = JSON.parse(event.data as string);
        } catch (error) {
          console.error("Failed to parse chat message", error);
          return;
        }
        if (isChatMessage(parsed)) {
          setMessages((prev) => [...prev, parsed]);
        }
      };

      socket.onclose = () => {
        if (isUnmountedRef.current) return;
        setIsReconnecting(true);
        reconnectTimeoutRef.current = setTimeout(connect, RECONNECT_DELAY_MS);
      };

      socket.onerror = () => {
        socket?.close();
      };
    };

    connect();

    return () => {
      isUnmountedRef.current = true;
      if (reconnectTimeoutRef.current !== null) {
        clearTimeout(reconnectTimeoutRef.current);
        reconnectTimeoutRef.current = null;
      }
      if (socketRef.current) {
        socketRef.current.onopen = null;
        socketRef.current.onmessage = null;
        socketRef.current.onclose = null;
        socketRef.current.onerror = null;
        socketRef.current.close();
        socketRef.current = null;
      }
      setIsReconnecting(false);
    };
  }, [roomId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = useCallback(() => {
    const text = draft.trim();
    const socket = socketRef.current;
    if (!text || !socket || socket.readyState !== WebSocket.OPEN) return;

    socket.send(JSON.stringify({ text }));
    setDraft("");
  }, [draft]);

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    sendMessage();
  };

  return (
    <div className="chat-room">
      {isReconnecting && <div className="chat-room__banner">Reconnecting...</div>}

      <div className="chat-room__messages">
        {messages.map((message) => (
          <div key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__time">
              {new Date(message.sentAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form className="chat-room__composer" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message..."
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  error: string | null;
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [loading, setLoading] = useState(ids.length > 0);
  const [error, setError] = useState<string | null>(null);

  const idsKey = ids.join(",");

  useEffect(() => {
    if (ids.length === 0) {
      setProfiles({});
      setLoading(false);
      setError(null);
      return;
    }

    const controller = new AbortController();
    setLoading(true);
    setError(null);

    Promise.all(
      ids.map(async (id) => {
        const response = await fetch(`/api/users/${id}`, { signal: controller.signal });
        if (!response.ok) {
          throw new Error(`Failed to load user ${id}: ${response.status}`);
        }
        return (await response.json()) as User;
      }),
    )
      .then((users) => {
        const byId: Record<string, User> = {};
        for (const user of users) {
          byId[user.id] = user;
        }
        setProfiles(byId);
      })
      .catch((err: unknown) => {
        if (err instanceof DOMException && err.name === "AbortError") {
          return;
        }
        setError(err instanceof Error ? err.message : "Failed to load profiles");
      })
      .finally(() => {
        setLoading(false);
      });

    return () => {
      controller.abort();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [idsKey]);

  return { profiles, loading, error };
}

import { useState } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const hasChanges = displayName !== user.displayName || bio !== user.bio;

  function handleReset() {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  }

  async function handleSave() {
    setIsSaving(true);
    setError(null);
    try {
      await onSave({ ...user, displayName, bio });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save profile");
    } finally {
      setIsSaving(false);
    }
  }

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        void handleSave();
      }}
    >
      <img src={user.avatarUrl} alt={`${user.displayName}'s avatar`} width={64} height={64} />

      <label>
        Display name
        <input
          type="text"
          value={displayName}
          onChange={(event) => setDisplayName(event.target.value)}
          disabled={isSaving}
        />
      </label>

      <label>
        Bio
        <textarea
          value={bio}
          onChange={(event) => setBio(event.target.value)}
          disabled={isSaving}
        />
      </label>

      <p>{hasChanges ? "Unsaved changes" : "No unsaved changes"}</p>
      {error && <p role="alert">{error}</p>}

      <button type="submit" disabled={isSaving || !hasChanges}>
        {isSaving ? "Saving..." : "Save"}
      </button>
      <button type="button" onClick={handleReset} disabled={isSaving || !hasChanges}>
        Reset
      </button>
    </form>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  errors: Record<string, string>;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

async function fetchUser(id: string): Promise<User> {
  const response = await fetch(`/api/users/${encodeURIComponent(id)}`);
  if (!response.ok) {
    throw new Error(`Failed to load user ${id}: ${response.status}`);
  }
  const data: unknown = await response.json();
  if (!isUser(data)) {
    throw new Error(`Invalid user data received for ${id}`);
  }
  return data;
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(ids.length > 0);

  useEffect(() => {
    if (ids.length === 0) {
      setProfiles({});
      setErrors({});
      setLoading(false);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setProfiles({});
    setErrors({});

    void Promise.all(
      ids.map(async (id) => {
        try {
          const user = await fetchUser(id);
          if (!cancelled) {
            setProfiles((prev) => ({ ...prev, [id]: user }));
          }
        } catch (err) {
          if (!cancelled) {
            const message = err instanceof Error ? err.message : `Failed to load user ${id}`;
            setErrors((prev) => ({ ...prev, [id]: message }));
          }
        }
      }),
    ).then(() => {
      if (!cancelled) {
        setLoading(false);
      }
    });

    return () => {
      cancelled = true;
    };
  }, [ids.join(",")]);

  return { profiles, loading, errors };
}

