import Foundation

// MARK: - Legacy callback-based SDK (stubs)

final class LegacyGeocoder {
    func geocode(_ address: String, completion: @escaping (Result<(Double, Double), Error>) -> Void) {
        DispatchQueue.global().asyncAfter(deadline: .now() + 0.1) {
            completion(.success((37.7749, -122.4194)))
        }
    }
}

final class LegacyUploader {
    var onProgress: ((Double) -> Void)?
    var onFinish: ((Error?) -> Void)?

    func start(file: URL) {
        DispatchQueue.global().async {
            for step in 1...10 {
                Thread.sleep(forTimeInterval: 0.01)
                self.onProgress?(Double(step) / 10.0)
            }
            self.onFinish?(nil)
        }
    }
}

// MARK: - Modern async/await wrappers

enum UploadClientError: Error {
    case uploadAlreadyInProgress
}

private extension NSLock {
    // `lock()`/`unlock()` are unavailable from async contexts; a synchronous
    // wrapper keeps the critical section itself non-async so it can still be
    // called from `async` methods.
    func withLock<T>(_ body: () -> T) -> T {
        lock()
        defer { unlock() }
        return body()
    }
}

func geocode(_ address: String) async throws -> (Double, Double) {
    // LegacyGeocoder has no cancel API; onCancel is a no-op so the callback's
    // eventual result is simply discarded by the (already-thrown) CancellationError.
    try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { continuation in
            LegacyGeocoder().geocode(address) { result in
                continuation.resume(with: result)
            }
        }
    } onCancel: {}
}

final class UploadClient {
    private let uploader = LegacyUploader()
    private let lock = NSLock()
    private var progressContinuation: AsyncStream<Double>.Continuation?
    private var isUploading = false

    /// Emits upload progress values in [0, 1]; finishes when the upload completes or fails.
    let progress: AsyncStream<Double>

    init() {
        var continuation: AsyncStream<Double>.Continuation!
        progress = AsyncStream { continuation = $0 }
        progressContinuation = continuation
        continuation.onTermination = { [weak self] _ in
            // Stop feeding a stream nobody is listening to anymore.
            self?.uploader.onProgress = nil
        }
    }

    func upload(file: URL) async throws {
        let alreadyUploading = lock.withLock { () -> Bool in
            if isUploading { return true }
            isUploading = true
            return false
        }
        guard !alreadyUploading else {
            throw UploadClientError.uploadAlreadyInProgress
        }

        uploader.onProgress = { [weak self] value in
            guard let self else { return }
            let continuation = self.lock.withLock { self.progressContinuation }
            continuation?.yield(value)
        }

        // LegacyUploader has no cancel API; onCancel is a no-op so any further
        // progress/finish callbacks are simply ignored once the task is abandoned.
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                uploader.onFinish = { [weak self] error in
                    guard let self else { return }
                    let progressContinuation = self.lock.withLock { () -> AsyncStream<Double>.Continuation? in
                        self.isUploading = false
                        return self.progressContinuation
                    }
                    progressContinuation?.finish()
                    if let error {
                        continuation.resume(throwing: error)
                    } else {
                        continuation.resume(returning: ())
                    }
                }
                uploader.start(file: file)
            }
        } onCancel: {}
    }
}

import SwiftUI

struct SearchResult: Identifiable, Codable {
    let id: String
    let title: String
    let subtitle: String
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = "" {
        didSet { scheduleSearch() }
    }
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private let debounceInterval: Duration
    private var searchTask: Task<Void, Never>?
    private let session: URLSession

    init(debounceInterval: Duration = .milliseconds(300), session: URLSession = .shared) {
        self.debounceInterval = debounceInterval
        self.session = session
    }

    private func scheduleSearch() {
        searchTask?.cancel()

        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            isLoading = false
            errorMessage = nil
            results = []
            return
        }

        searchTask = Task { [debounceInterval] in
            do {
                try await Task.sleep(for: debounceInterval)
            } catch {
                return
            }
            guard !Task.isCancelled else { return }
            await self.performSearch(for: trimmed)
        }
    }

    private func performSearch(for term: String) async {
        isLoading = true
        errorMessage = nil

        guard var components = URLComponents(string: "https://api.example.com/search") else {
            isLoading = false
            errorMessage = "Invalid search URL."
            return
        }
        components.queryItems = [URLQueryItem(name: "q", value: term)]

        guard let url = components.url else {
            isLoading = false
            errorMessage = "Invalid search URL."
            return
        }

        do {
            let (data, response) = try await session.data(from: url)

            guard !Task.isCancelled else { return }

            if let httpResponse = response as? HTTPURLResponse, !(200...299).contains(httpResponse.statusCode) {
                isLoading = false
                errorMessage = "Search failed with status code \(httpResponse.statusCode)."
                return
            }

            let decoded = try JSONDecoder().decode([SearchResult].self, from: data)

            guard !Task.isCancelled else { return }

            results = decoded
            isLoading = false
        } catch is CancellationError {
            // A newer search superseded this one; leave state as-is.
        } catch {
            guard !Task.isCancelled else { return }
            isLoading = false
            errorMessage = error.localizedDescription
            results = []
        }
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel: SearchViewModel

    @MainActor
    init(viewModel: SearchViewModel? = nil) {
        _viewModel = StateObject(wrappedValue: viewModel ?? SearchViewModel())
    }

    var body: some View {
        VStack(spacing: 0) {
            TextField("Search", text: $viewModel.query)
                .textFieldStyle(.roundedBorder)
                .padding()

            content
        }
        .frame(minWidth: 320, minHeight: 400)
    }

    @ViewBuilder
    private var content: some View {
        if viewModel.isLoading {
            Spacer()
            ProgressView("Searching…")
            Spacer()
        } else if let errorMessage = viewModel.errorMessage {
            Spacer()
            Text(errorMessage)
                .foregroundStyle(.red)
                .multilineTextAlignment(.center)
                .padding()
            Spacer()
        } else if viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            Spacer()
            Text("Start typing to search.")
                .foregroundStyle(.secondary)
            Spacer()
        } else if viewModel.results.isEmpty {
            Spacer()
            Text("No results found.")
                .foregroundStyle(.secondary)
            Spacer()
        } else {
            List(viewModel.results) { result in
                VStack(alignment: .leading) {
                    Text(result.title)
                        .font(.headline)
                    Text(result.subtitle)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            }
        }
    }
}

import SwiftUI
import Combine
import Foundation

struct SearchResult: Identifiable, Decodable {
    let id: String
    let title: String
    let subtitle: String
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = ""
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private var cancellables = Set<AnyCancellable>()
    private var searchTask: Task<Void, Never>?
    private let session: URLSession

    init(session: URLSession = .shared) {
        self.session = session

        $query
            .debounce(for: .milliseconds(300), scheduler: DispatchQueue.main)
            .removeDuplicates()
            .sink { [weak self] text in
                self?.scheduleSearch(for: text)
            }
            .store(in: &cancellables)
    }

    private func scheduleSearch(for text: String) {
        searchTask?.cancel()

        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            results = []
            errorMessage = nil
            isLoading = false
            return
        }

        searchTask = Task { [weak self] in
            await self?.performSearch(query: trimmed)
        }
    }

    private func performSearch(query: String) async {
        isLoading = true
        errorMessage = nil

        var components = URLComponents(string: "https://api.example.com/search")
        components?.queryItems = [URLQueryItem(name: "q", value: query)]

        guard let url = components?.url else {
            isLoading = false
            errorMessage = "Couldn't build a search request for that query."
            return
        }

        do {
            let (data, response) = try await session.data(from: url)
            try Task.checkCancellation()

            if let httpResponse = response as? HTTPURLResponse, !(200..<300).contains(httpResponse.statusCode) {
                isLoading = false
                errorMessage = "The server returned status \(httpResponse.statusCode)."
                return
            }

            let decoded = try JSONDecoder().decode([SearchResult].self, from: data)
            try Task.checkCancellation()

            results = decoded
            isLoading = false
        } catch is CancellationError {
            // A newer search superseded this one; leave state as-is.
        } catch {
            if !Task.isCancelled {
                isLoading = false
                errorMessage = "Couldn't load results: \(error.localizedDescription)"
            }
        }
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    private var trimmedQuery: String {
        viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines)
    }

