import SwiftUI
import Foundation
import os

struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatViewModel: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []
    @Published var draft: String = ""

    // "wss://chat.example.com/room" is a well-formed literal, but URL(string:) still
    // returns an Optional; fall back to a clearly-invalid placeholder instead of force-unwrapping.
    private static let roomURL: URL = URL(string: "wss://chat.example.com/room") ?? URL(fileURLWithPath: "/dev/null")
    private nonisolated static let logger = Logger(subsystem: "App", category: "ChatViewModel")

    private let session = URLSession(configuration: .default)
    private var socketTask: URLSessionWebSocketTask?

    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    private var isStopped = false

    func start() {
        isStopped = false
        connect()
    }

    func stop() {
        isStopped = true
        socketTask?.cancel(with: .goingAway, reason: nil)
        socketTask = nil
    }

    func send() {
        let trimmedText = draft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedText.isEmpty, let socketTask else { return }
        draft = ""

        let outgoingMessage = ChatMessage(id: UUID().uuidString, author: "me", text: trimmedText)
        guard let encodedMessage = try? JSONEncoder().encode(outgoingMessage) else { return }
        socketTask.send(.data(encodedMessage)) { [weak self] error in
            guard let error else { return }
            Self.logger.error("WebSocket send failed: \(error.localizedDescription)")
            Task { @MainActor in
                self?.handleFailure()
            }
        }
    }

    private func connect() {
        let newTask = session.webSocketTask(with: Self.roomURL)
        socketTask = newTask
        newTask.resume()
        listen(on: newTask)
    }

    private func listen(on activeTask: URLSessionWebSocketTask) {
        activeTask.receive { [weak self] result in
            Task { @MainActor in
                guard let self, self.socketTask === activeTask else { return }
                switch result {
                case .success(let webSocketMessage):
                    self.handle(webSocketMessage)
                    self.listen(on: activeTask)
                case .failure(let error):
                    Self.logger.error("WebSocket receive failed: \(error.localizedDescription)")
                    self.handleFailure()
                }
            }
        }
    }

    private func handle(_ webSocketMessage: URLSessionWebSocketTask.Message) {
        let payload: Data
        switch webSocketMessage {
        case .data(let binaryPayload):
            payload = binaryPayload
        case .string(let textPayload):
            payload = Data(textPayload.utf8)
        @unknown default:
            return
        }
        guard let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: payload) else { return }
        messages.append(chatMessage)
    }

    private func handleFailure() {
        guard !isStopped else { return }
        socketTask?.cancel(with: .abnormalClosure, reason: nil)
        socketTask = nil
        scheduleReconnect()
    }

    private func scheduleReconnect() {
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        Task { [weak self] in
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard let self, !self.isStopped else { return }
            self.connect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var viewModel = ChatViewModel()

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { scrollProxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(viewModel.messages) { chatMessage in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(chatMessage.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(chatMessage.text)
                            }
                            .id(chatMessage.id)
                            .frame(maxWidth: .infinity, alignment: .leading)
                        }
                    }
                    .padding()
                }
                .onChange(of: viewModel.messages) { _ in
                    guard let lastMessage = viewModel.messages.last else { return }
                    withAnimation {
                        scrollProxy.scrollTo(lastMessage.id, anchor: .bottom)
                    }
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $viewModel.draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit { viewModel.send() }
                Button("Send") { viewModel.send() }
                    .disabled(viewModel.draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .task {
            viewModel.start()
        }
        .onDisappear {
            viewModel.stop()
        }
    }
}

import Foundation
import SwiftUI

struct Lap: Identifiable {
    let id = UUID()
    let number: Int
    /// Elapsed time since the stopwatch started, at the moment this lap was recorded.
    let splitTime: TimeInterval
    /// Time elapsed since the previous lap.
    let lapTime: TimeInterval
}

final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsedTime: TimeInterval = 0
    @Published private(set) var laps: [Lap] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startDate: Date?
    private var accumulatedTime: TimeInterval = 0

    var formattedElapsedTime: String {
        Self.format(elapsedTime)
    }

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startDate = Date()
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            self?.tick()
        }
    }

    func stop() {
        guard isRunning else { return }
        timer?.invalidate()
        timer = nil
        if let startDate {
            accumulatedTime += Date().timeIntervalSince(startDate)
        }
        startDate = nil
        isRunning = false
        elapsedTime = accumulatedTime
    }

    func reset() {
        stop()
        elapsedTime = 0
        accumulatedTime = 0
        laps = []
    }

    func lap() {
        guard isRunning else { return }
        let previousSplit = laps.first?.splitTime ?? 0
        let newLap = Lap(number: laps.count + 1, splitTime: elapsedTime, lapTime: elapsedTime - previousSplit)
        laps.insert(newLap, at: 0)
    }

    private func tick() {
        guard let startDate else { return }
        elapsedTime = accumulatedTime + Date().timeIntervalSince(startDate)
    }

    static func format(_ time: TimeInterval) -> String {
        let totalCentiseconds = Int((time * 100).rounded())
        let minutes = totalCentiseconds / 6000
        let seconds = (totalCentiseconds / 100) % 60
        let centiseconds = totalCentiseconds % 100
        return String(format: "%02d:%02d.%02d", minutes, seconds, centiseconds)
    }
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 24) {
            Text(viewModel.formattedElapsedTime)
                .font(.system(size: 56, weight: .medium, design: .monospaced))
                .monospacedDigit()

            HStack(spacing: 16) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    if viewModel.isRunning {
                        viewModel.stop()
                    } else {
                        viewModel.start()
                    }
                }
                .keyboardShortcut(.defaultAction)

                Button("Lap") {
                    viewModel.lap()
                }
                .disabled(!viewModel.isRunning)

                Button("Reset") {
                    viewModel.reset()
                }
                .disabled(viewModel.isRunning || viewModel.elapsedTime == 0)
            }

            List(viewModel.laps) { lap in
                HStack {
                    Text("Lap \(lap.number)")
                        .foregroundStyle(.secondary)
                    Spacer()
                    Text(StopwatchViewModel.format(lap.lapTime))
                    Text(StopwatchViewModel.format(lap.splitTime))
                        .foregroundStyle(.secondary)
                        .frame(width: 90, alignment: .trailing)
                }
            }
            .frame(minHeight: 120)
        }
        .padding()
        .frame(minWidth: 320)
    }
}

