import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  error: string | null;
}

const MAX_CONCURRENT_REQUESTS = 4;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

async function fetchUser(id: string): Promise<User> {
  const response = await fetch(`/api/users/${id}`);
  if (!response.ok) {
    throw new Error(`Failed to load user ${id}: ${response.status}`);
  }
  const responseBody: unknown = await response.json();
  if (!isUser(responseBody)) {
    throw new Error(`Received malformed profile data for user ${id}`);
  }
  return responseBody;
}

async function fetchUsersWithConcurrencyLimit(ids: string[], limit: number): Promise<User[]> {
  const results: User[] = new Array(ids.length);
  let nextIndex = 0;

  async function worker() {
    while (nextIndex < ids.length) {
      const currentIndex = nextIndex;
      nextIndex += 1;
      results[currentIndex] = await fetchUser(ids[currentIndex]);
    }
  }

  const workers = Array.from({ length: Math.min(limit, ids.length) }, () => worker());
  await Promise.all(workers);
  return results;
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [loading, setLoading] = useState(ids.length > 0);
  const [error, setError] = useState<string | null>(null);

  const key = ids.join(",");

  useEffect(() => {
    if (ids.length === 0) {
      setProfiles({});
      setLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchUsersWithConcurrencyLimit(ids, MAX_CONCURRENT_REQUESTS)
      .then((users) => {
        if (cancelled) return;
        const byId: Record<string, User> = {};
        for (const user of users) {
          byId[user.id] = user;
        }
        setProfiles(byId);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to load profiles");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  return { profiles, loading, error };
}

import { useState } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const hasChanges = displayName !== user.displayName || bio !== user.bio;

  const handleReset = () => {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  };

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      await onSave({ ...user, displayName, bio });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save profile");
    } finally {
      setSaving(false);
    }
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        void handleSave();
      }}
    >
      <img src={user.avatarUrl} alt={`${displayName}'s avatar`} width={64} height={64} />

      <label htmlFor="displayName">Display name</label>
      <input
        id="displayName"
        value={displayName}
        onChange={(e) => setDisplayName(e.target.value)}
        disabled={saving}
      />

      <label htmlFor="bio">Bio</label>
      <textarea
        id="bio"
        value={bio}
        onChange={(e) => setBio(e.target.value)}
        disabled={saving}
      />

      <p>{hasChanges ? "Unsaved changes" : "No unsaved changes"}</p>
      {error && <p role="alert">{error}</p>}

      <button type="submit" disabled={saving || !hasChanges}>
        {saving ? "Saving..." : "Save"}
      </button>
      <button type="button" onClick={handleReset} disabled={saving || !hasChanges}>
        Reset
      </button>
    </form>
  );
}

