final class LegacyUploader {
    var onProgress: ((Double) -> Void)?
    var onFinish: ((Error?) -> Void)?

    func start(file: URL) {
        DispatchQueue.global().async {
            for step in 1...10 {
                Thread.sleep(forTimeInterval: 0.01)
                self.onProgress?(Double(step) / 10.0)
            }
            self.onFinish?(nil)
        }
