// MARK: - Modern async/await wrappers

enum GeocodingError: Error {
    case notFound
}

func geocode(_ address: String) async throws -> (Double, Double) {
    let geocoder = LegacyGeocoder()
    // LegacyGeocoder has no cancel API, so task cancellation can't stop the
    // in-flight lookup; the handler just documents that limitation.
    return try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { continuation in
            geocoder.geocode(address) { result in
                continuation.resume(with: result)
            }
        }
    } onCancel: {}
}

/// Serializes access to the legacy uploader's mutable callback state so two
/// overlapping `upload(file:)` calls can't clobber each other's continuation.
actor Uploader {
    enum UploadError: Error {
        case alreadyInProgress
    }

    private let legacyUploader = LegacyUploader()
    private var isUploading = false
    private var progressContinuation: AsyncStream<Double>.Continuation?

    /// Emits upload progress values (0...1) as they arrive from the legacy callback.
    nonisolated let progress: AsyncStream<Double>

    init() {
        var continuation: AsyncStream<Double>.Continuation!
        progress = AsyncStream<Double> { cont in
            continuation = cont
        }
        progressContinuation = continuation
        continuation.onTermination = { [weak self] _ in
            // Release our reference once the consumer stops iterating (or the
            // stream is torn down) so we stop yielding into a dead stream.
            guard let self else { return }
            Task { await self.clearProgressContinuation() }
        }
    }

    private func clearProgressContinuation() {
        progressContinuation = nil
    }

    func upload(file: URL) async throws {
        guard !isUploading else { throw UploadError.alreadyInProgress }
        isUploading = true
        defer { isUploading = false }

        let progressContinuation = progressContinuation
        // As with geocode, LegacyUploader has no cancel API; the underlying
        // transfer keeps running even if this Task is cancelled.
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                legacyUploader.onProgress = { value in
                    progressContinuation?.yield(value)
                }
                legacyUploader.onFinish = { error in
                    if let error {
                        continuation.resume(throwing: error)
                    } else {
                        continuation.resume(returning: ())
                    }
                }
                legacyUploader.start(file: file)
            }
        } onCancel: {}
    }
}

import Foundation
import SwiftUI

enum ThemeChoice: String, CaseIterable, Identifiable {
    case system
    case light
    case dark

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .system: return "System"
        case .light: return "Light"
        case .dark: return "Dark"
        }
    }
}

final class SettingsStore: ObservableObject {
    private enum Keys {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    @Published var displayName: String {
        didSet { persist(displayName, forKey: Keys.displayName) }
    }
    @Published var theme: ThemeChoice {
        didSet { persist(theme.rawValue, forKey: Keys.theme) }
    }
    @Published var notificationsEnabled: Bool {
        didSet { persist(notificationsEnabled, forKey: Keys.notificationsEnabled) }
    }
    @Published var refreshInterval: TimeInterval {
        didSet { persist(refreshInterval, forKey: Keys.refreshInterval) }
    }

    private let defaults: UserDefaults
    // Guards against the write -> didChangeNotification -> reload -> write loop.
    private var isApplyingExternalChange = false
    private var observer: NSObjectProtocol?

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        self.displayName = defaults.string(forKey: Keys.displayName) ?? ""
        self.theme = ThemeChoice(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        self.notificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        self.refreshInterval = defaults.object(forKey: Keys.refreshInterval) as? TimeInterval ?? 60

        observer = NotificationCenter.default.addObserver(
            forName: UserDefaults.didChangeNotification,
            object: defaults,
            queue: .main
        ) { [weak self] _ in
            self?.reloadFromDefaults()
        }
    }

    deinit {
        if let observer {
            NotificationCenter.default.removeObserver(observer)
        }
    }

    private func persist<T>(_ value: T, forKey key: String) {
        guard !isApplyingExternalChange else { return }
        defaults.set(value, forKey: key)
    }

    private func reloadFromDefaults() {
        isApplyingExternalChange = true
        defer { isApplyingExternalChange = false }

        let newDisplayName = defaults.string(forKey: Keys.displayName) ?? ""
        if newDisplayName != displayName { displayName = newDisplayName }

        let newTheme = ThemeChoice(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        if newTheme != theme { theme = newTheme }

        let newNotificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        if newNotificationsEnabled != notificationsEnabled { notificationsEnabled = newNotificationsEnabled }

        let newRefreshInterval = defaults.object(forKey: Keys.refreshInterval) as? TimeInterval ?? 60
        if newRefreshInterval != refreshInterval { refreshInterval = newRefreshInterval }
    }
}

struct SettingsScreen: View {
    @ObservedObject var store: SettingsStore

    var body: some View {
        Form {
            Section("Profile") {
                TextField("Display Name", text: $store.displayName)
            }

            Section("Appearance") {
                Picker("Theme", selection: $store.theme) {
                    ForEach(ThemeChoice.allCases) { theme in
                        Text(theme.displayName).tag(theme)
                    }
                }
            }

            Section("Notifications") {
                Toggle("Enable Notifications", isOn: $store.notificationsEnabled)
            }

            Section("Refresh Interval") {
                Stepper(value: $store.refreshInterval, in: 15...3600, step: 15) {
