struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatViewModel: ObservableObject {
    @Published var messages: [ChatMessage] = []
    @Published var draft: String = ""

    let author = "Me"

    private static let nanosecondsPerSecond: UInt64 = 1_000_000_000
    private static let maxReconnectDelaySeconds: UInt64 = 30
    private static let initialReconnectDelaySeconds: UInt64 = 1

    private static func makeChatURL() -> URL {
        guard let url = URL(string: "wss://chat.example.com/room") else {
            preconditionFailure("Invalid chat URL")
        }
        return url
    }

    private let url = ChatViewModel.makeChatURL()
    private let session = URLSession(configuration: .default)
    private var webSocketTask: URLSessionWebSocketTask?
    private var reconnectDelaySeconds = ChatViewModel.initialReconnectDelaySeconds
    private var isStopped = false

    func connect() {
        isStopped = false
        let task = session.webSocketTask(with: url)
        webSocketTask = task
        task.resume()
        listen(on: task)
    }

    func stop() {
        isStopped = true
        webSocketTask?.cancel(with: .goingAway, reason: nil)
        webSocketTask = nil
    }

    private func listen(on task: URLSessionWebSocketTask) {
        task.receive { [weak self] result in
            guard let self else { return }
            Task { @MainActor in
                switch result {
                case .failure:
                    self.handleDisconnect()
                case .success(let message):
                    self.handle(message)
                    guard task === self.webSocketTask else { return }
                    self.listen(on: task)
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = Data(text.utf8)
        @unknown default:
            return
        }

        guard let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
        reconnectDelaySeconds = 1
    }

    private func handleDisconnect() {
        webSocketTask = nil
        guard !isStopped else { return }

        let delay = reconnectDelaySeconds
        reconnectDelaySeconds = min(reconnectDelaySeconds * 2, Self.maxReconnectDelaySeconds)

        Task { @MainActor in
            try? await Task.sleep(nanoseconds: delay * Self.nanosecondsPerSecond)
            guard !self.isStopped else { return }
            self.connect()
        }
    }

    func sendDraft() {
        let trimmed = draft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        draft = ""

        let outgoing = ChatMessage(id: UUID().uuidString, author: author, text: trimmed)
        guard let data = try? JSONEncoder().encode(outgoing),
              let json = String(data: data, encoding: .utf8) else { return }

        webSocketTask?.send(.string(json)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                self?.handleDisconnect()
            }
        }
    }
}

struct ChatScreen: View {
    @StateObject private var viewModel = ChatViewModel()

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
