import SwiftUI
import AppKit

struct CachedThumbnail {
    let image: Image
    let downloadDate: Date
}

actor ThumbnailCache {
    static let shared = ThumbnailCache()

    private var storage: [URL: CachedThumbnail] = [:]

    func thumbnail(for url: URL) -> CachedThumbnail? {
        storage[url]
    }

    func store(_ thumbnail: CachedThumbnail, for url: URL) {
        storage[url] = thumbnail
    }
}

@MainActor
final class ThumbnailLoader: ObservableObject {
    @Published private(set) var thumbnail: CachedThumbnail?

    func load(from url: URL) async {
        if let cached = await ThumbnailCache.shared.thumbnail(for: url) {
            thumbnail = cached
            return
        }

        guard let (data, _) = try? await URLSession.shared.data(from: url),
              let nsImage = NSImage(data: data) else {
            return
        }

        let loaded = CachedThumbnail(image: Image(nsImage: nsImage), downloadDate: Date())
        await ThumbnailCache.shared.store(loaded, for: url)
        thumbnail = loaded
    }
}

private let relativeDateFormatter: RelativeDateTimeFormatter = {
    let formatter = RelativeDateTimeFormatter()
    formatter.unitsStyle = .abbreviated
    return formatter
}()

private struct ThumbnailCell: View {
    let url: URL

    @StateObject private var loader = ThumbnailLoader()

    var body: some View {
        VStack(spacing: 4) {
            Group {
                if let thumbnail = loader.thumbnail {
                    thumbnail.image
                        .resizable()
                        .scaledToFill()
                } else {
                    ProgressView()
                }
            }
            .frame(width: 100, height: 100)
            .background(Color.gray.opacity(0.2))
            .clipShape(RoundedRectangle(cornerRadius: 8))

            if let thumbnail = loader.thumbnail {
                Text(relativeDateFormatter.localizedString(for: thumbnail.downloadDate, relativeTo: Date()))
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
        }
        .task(id: url) {
            await loader.load(from: url)
        }
    }
}

