import SwiftUI

struct Lap: Identifiable {
    let id = UUID()
    let number: Int
    let totalTime: TimeInterval
    let splitTime: TimeInterval
}

@MainActor
final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsed: TimeInterval = 0
    @Published private(set) var laps: [Lap] = []
    @Published private(set) var isRunning: Bool = false

    private var timer: Timer?
    private var startDate: Date?
    private var accumulated: TimeInterval = 0

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startDate = Date()
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            guard let self else { return }
            Task { @MainActor in
                self.tick()
            }
        }
    }

    func stop() {
        guard isRunning else { return }
        isRunning = false
        timer?.invalidate()
        timer = nil
        accumulated = elapsed
        startDate = nil
    }

    func reset() {
        stop()
        elapsed = 0
        accumulated = 0
        laps.removeAll()
    }

    func lap() {
        let previousTotal = laps.last?.totalTime ?? 0
        laps.append(Lap(number: laps.count + 1, totalTime: elapsed, splitTime: elapsed - previousTotal))
    }

    private func tick() {
        guard let startDate else { return }
        elapsed = accumulated + Date().timeIntervalSince(startDate)
    }
}

private func formattedTime(_ interval: TimeInterval) -> String {
    let totalHundredths = Int((interval * 100).rounded())
    let minutes = (totalHundredths / 100) / 60
    let seconds = (totalHundredths / 100) % 60
    let hundredths = totalHundredths % 100
    return String(format: "%02d:%02d.%02d", minutes, seconds, hundredths)
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 20) {
            Text(formattedTime(viewModel.elapsed))
                .font(.system(size: 48, weight: .medium, design: .monospaced))
                .monospacedDigit()

            HStack(spacing: 12) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    viewModel.isRunning ? viewModel.stop() : viewModel.start()
                }
                Button("Lap") {
                    viewModel.lap()
                }
                .disabled(!viewModel.isRunning)
                Button("Reset") {
                    viewModel.reset()
                }
                .disabled(viewModel.isRunning && viewModel.elapsed == 0)
            }
            .buttonStyle(.bordered)

            List {
                ForEach(viewModel.laps.reversed()) { lap in
                    HStack {
                        Text("Lap \(lap.number)")
                            .foregroundStyle(.secondary)
                        Spacer()
                        Text(formattedTime(lap.splitTime))
                            .monospacedDigit()
                        Spacer()
                        Text(formattedTime(lap.totalTime))
                            .monospacedDigit()
                            .foregroundStyle(.secondary)
                    }
                }
            }
        }
        .padding()
        .frame(minWidth: 300, minHeight: 400)
    }
}

