struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

// wss://chat.example.com/room is a well-formed literal, but URL(string:) is still
// failable, so fall back to a harmless placeholder rather than force-unwrapping.
private let defaultChatURL = URL(string: "wss://chat.example.com/room")
    ?? URL(fileURLWithPath: NSTemporaryDirectory())

@MainActor
final class ChatConnection: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []

    private let url: URL
    private let session: URLSession
    private var task: URLSessionWebSocketTask?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    private var isStopped = false

    init(url: URL = defaultChatURL) {
        self.url = url
        self.session = URLSession(configuration: .default)
    }

    func connect() {
        isStopped = false
        let task = session.webSocketTask(with: url)
        self.task = task
        task.resume()
        reconnectDelay = 1
        receiveNext()
    }

    func disconnect() {
        isStopped = true
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
    }

    func send(text: String) {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        let message = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(message) else { return }
        task?.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                self?.scheduleReconnect()
            }
        }
        messages.append(message)
    }

    private func receiveNext() {
        task?.receive { [weak self] result in
            guard let self else { return }
            Task { @MainActor in
                switch result {
                case .failure:
                    self.scheduleReconnect()
                case .success(let message):
                    self.handle(message)
                    self.receiveNext()
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = Data(text.utf8)
        @unknown default:
            return
        }
        guard let decoded = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(decoded)
    }

    private func scheduleReconnect() {
        guard !isStopped else { return }
        task = nil
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            guard let self, !self.isStopped else { return }
            self.connect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var connection = ChatConnection()
    @State private var draft: String = ""

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(connection.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .padding(.horizontal)
                        }
                    }
                    .padding(.vertical, 8)
                }
                .onChange(of: connection.messages) { _ in
                    scrollToBottom(proxy: proxy)
                }
                .onAppear {
                    scrollToBottom(proxy: proxy)
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $draft, onCommit: sendDraft)
                Button("Send", action: sendDraft)
                    .disabled(draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onAppear { connection.connect() }
        .onDisappear { connection.disconnect() }
    }

    private func sendDraft() {
        connection.send(text: draft)
        draft = ""
    }

    private func scrollToBottom(proxy: ScrollViewProxy) {
        guard let last = connection.messages.last else { return }
        withAnimation {
            proxy.scrollTo(last.id, anchor: .bottom)
        }
    }
}

import Foundation

// MARK: - Legacy callback-based SDK (stubs)

final class LegacyGeocoder {
    func geocode(_ address: String, completion: @escaping (Result<(Double, Double), Error>) -> Void) {
        DispatchQueue.global().asyncAfter(deadline: .now() + 0.1) {
            completion(.success((37.7749, -122.4194)))
        }
    }
}

final class LegacyUploader {
    var onProgress: ((Double) -> Void)?
    var onFinish: ((Error?) -> Void)?

    func start(file: URL) {
        DispatchQueue.global().async { [weak self] in
            guard let self else { return }
            for step in 1...5 {
                Thread.sleep(forTimeInterval: 0.05)
                self.onProgress?(Double(step) / 5.0)
            }
            self.onFinish?(nil)
        }
    }
}

// MARK: - Continuation helper

/// Guards a `CheckedContinuation` so it is resumed at most once even when the
/// legacy completion handler and a task-cancellation handler can both fire it
/// concurrently from different threads.
private final class ResumeBox<T>: @unchecked Sendable {
    private let lock = NSLock()
    private var continuation: CheckedContinuation<T, Error>?

    func set(_ continuation: CheckedContinuation<T, Error>) {
        lock.lock(); defer { lock.unlock() }
        self.continuation = continuation
    }

    func resume(with result: Result<T, Error>) {
        lock.lock()
        let continuation = self.continuation
        self.continuation = nil
        lock.unlock()
        continuation?.resume(with: result)
    }
}

/// Thrown when a bridge method is called while a previous call is still in flight,
/// since the underlying legacy object only supports one callback set at a time.
enum LegacyBridgeError: Error {
    case alreadyInFlight
}

/// Serializes access to an in-flight flag using actor isolation, which (unlike
/// `NSLock`) is safe to await from `async` call sites.
private actor InFlightGate {
    private var isInFlight = false

    func begin() throws {
        guard !isInFlight else { throw LegacyBridgeError.alreadyInFlight }
        isInFlight = true
    }

    func end() {
        isInFlight = false
    }
}

// MARK: - async/await bridges

final class GeocoderBridge: @unchecked Sendable {
    private let geocoder = LegacyGeocoder()
    private let gate = InFlightGate()

    func geocode(_ address: String) async throws -> (Double, Double) {
        try await gate.begin()
        do {
            let result = try await performGeocode(address)
            await gate.end()
            return result
        } catch {
            await gate.end()
            throw error
        }
    }

    private func performGeocode(_ address: String) async throws -> (Double, Double) {
        let box = ResumeBox<(Double, Double)>()
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                box.set(continuation)
                geocoder.geocode(address) { result in
                    box.resume(with: result)
                }
            }
        } onCancel: {
            // The legacy geocoder has no cancellation hook; at least unblock
            // the caller immediately instead of waiting for its completion.
            box.resume(with: .failure(CancellationError()))
        }
    }
}

final class UploaderBridge: @unchecked Sendable {
    /// Progress values in `0...1`, reported many times over the course of an upload.
    let progress: AsyncStream<Double>

    private let progressContinuation: AsyncStream<Double>.Continuation
    private let uploader = LegacyUploader()
    private let gate = InFlightGate()

    init() {
        var continuation: AsyncStream<Double>.Continuation!
        progress = AsyncStream { continuation = $0 }
        progressContinuation = continuation
        let uploader = self.uploader
        progressContinuation.onTermination = { _ in
            // If the consumer stops iterating early, drop the legacy
            // callbacks so they don't keep yielding into a dead stream.
            uploader.onProgress = nil
            uploader.onFinish = nil
        }
    }

    func upload(file: URL) async throws {
        try await gate.begin()
        do {
            try await performUpload(file: file)
            await gate.end()
        } catch {
            await gate.end()
            throw error
        }
    }

    private func performUpload(file: URL) async throws {
        let box = ResumeBox<Void>()
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                box.set(continuation)
                let progressContinuation = self.progressContinuation
                uploader.onProgress = { value in
                    progressContinuation.yield(value)
                }
                uploader.onFinish = { error in
                    progressContinuation.finish()
                    if let error {
                        box.resume(with: .failure(error))
                    } else {
                        box.resume(with: .success(()))
                    }
                }
                uploader.start(file: file)
            }
        } onCancel: {
            // The legacy uploader has no cancellation hook; at least unblock
            // the caller immediately instead of waiting for its completion.
            box.resume(with: .failure(CancellationError()))
        }
    }
}
